1	// KOL / Agency partner commission engine.
2	//
3	// The peer-referral program (lib/actions-growth.ts maybeRewardReferral +
4	// User.referralCode/referredById + AffiliatePayout) pays a customer a ONE-TIME
5	// wallet bonus for referring a friend. THIS module is a separate, additive
6	// program for agencies / content creators (KOLs): a partner is permanently
7	// attached to a customer they brought on (PartnerCustomer) and earns a LIFETIME
8	// percentage on EVERY qualifying charge that customer makes — the initial order
9	// AND every renewal, across all products — recorded as a PartnerCommission row.
10	//
11	// Idempotency: PartnerCommission.invoiceId is UNIQUE, so at most one commission
12	// row can ever exist per charge. Every accrual path (the inline hooks after an
13	// order/renewal, and the background reconciliation sweep) funnels through
14	// `accrueCommissionForInvoice`, which swallows the unique-violation on a
15	// re-attempt. A partner therefore can never be double-accrued for one charge.
16	
17	import { db } from "./db";
18	import type { Invoice, Prisma } from "@prisma/client";
19	
20	/**
21	 * Invoice descriptions that are NOT service sales and must never earn commission:
22	 *  - wallet top-ups (money IN, not a purchase — the service it later funds is its
23	 *    own invoice and is what earns the commission; accruing on both would double
24	 *    count). "Wallet top-up" is lib/stripe.ts; "Automatic wallet top-up" is the
25	 *    auto-recharge in worker/billing.ts (AUTO_RECHARGE_DESC).
26	 * Refunds/credits are excluded separately by the `amountCents <= 0` guard below.
27	 */
28	export const NON_COMMISSIONABLE_DESCRIPTIONS = new Set(["Wallet top-up", "Automatic wallet top-up"]);
29	
30	export type CommissionableInvoice = Pick<
31	  Invoice,
32	  "id" | "userId" | "status" | "amountCents" | "taxCents" | "description" | "createdAt" | "dedicatedIpCents"
33	>;
34	
35	/**
36	 * Is this invoice a qualifying charge a partner earns commission on? True for any
37	 * PAID invoice with a positive total that isn't a wallet top-up. This is the one
38	 * classifier every accrual path shares.
39	 */
40	export function isCommissionableInvoice(inv: CommissionableInvoice): boolean {
41	  if (inv.status !== "PAID") return false;
42	  if (inv.amountCents <= 0) return false; // refunds / zero-value docs
43	  if (NON_COMMISSIONABLE_DESCRIPTIONS.has(inv.description.trim())) return false;
44	  return true;
45	}
46	
47	/**
48	 * The commission BASE for an invoice: net (pre-tax) charge, minus the dedicated-IP
49	 * portion of it — the owner's spec is explicit that a partner earns 0% commission
50	 * on a dedicated-IP add-on line, but 100% of the normal rate on every other line
51	 * in the same order/renewal (base plan, extra disk, backup tier, any other
52	 * add-on). Pure function — no DB — so it's directly unit-tested
53	 * (test/partner-discount.test.ts) against the boundary cases: an order with only
54	 * a dedicated IP (base -> 0), an order with no dedicated IP (unaffected), and a
55	 * mixed-addon order (only the IP slice excluded). Clamped so a corrupt/negative
56	 * `dedicatedIpCents` can never inflate the base past the net charge.
57	 */
58	export function commissionableBaseCents(netCents: number, dedicatedIpCents: number): number {
59	  const ip = Math.max(0, dedicatedIpCents || 0);
60	  return Math.max(0, netCents - ip);
61	}
62	
63	/** Coarse kind label for the ledger, inferred from the invoice description. */
64	function inferKind(description: string): "ORDER" | "RENEWAL" | "CHARGE" {
65	  const d = description.toLowerCase();
66	  if (d.includes("renewal") || d.startsWith("renew")) return "RENEWAL";
67	  if (d.startsWith("order:")) return "ORDER";
68	  return "CHARGE";
69	}
70	
71	/**
72	 * Accrue the partner commission for a single qualifying invoice, IF the invoice's
73	 * owner is attached to an ACTIVE partner and no commission has been recorded yet.
74	 *
75	 * Idempotent and safe to call from anywhere, any number of times:
76	 *  - not commissionable / no partner attachment / paused partner  -> returns null.
77	 *  - a commission already exists for the invoice (unique invoiceId) -> returns null
78	 *    (the create throws P2002, which is swallowed).
79	 * Commission is computed on the NET (pre-tax) charge = amountCents - taxCents.
80	 *
81	 * Never throws for the "expected" cases; unexpected DB errors DO propagate so the
82	 * caller (which wraps this best-effort) can log them.
83	 */
84	export async function accrueCommissionForInvoice(
85	  inv: CommissionableInvoice
86	): Promise<{ commissionId: string; amountCents: number } | null> {
87	  if (!isCommissionableInvoice(inv)) return null;
88	
89	  const attachment = await db.partnerCustomer.findUnique({
90	    where: { customerId: inv.userId },
91	    include: { partner: true },
92	  });
93	  if (!attachment) return null;
94	  const partner = attachment.partner;
95	  if (partner.status !== "ACTIVE") return null;
96	
97	  // FUTURE-ONLY attribution: a partner earns only on charges dated at/after the
98	  // customer was attached to them. Attaching an existing customer therefore never
99	  // back-bills their prior invoices (no surprise retroactive liability); it starts
100	  // the lifetime clock from the attachment forward.
101	  if (inv.createdAt < attachment.createdAt) return null;
102	
103	  const rate = Number.isFinite(partner.commissionRatePct) ? partner.commissionRatePct : 0;
104	  if (rate <= 0) return null;
105	
106	  const netCents = Math.max(0, inv.amountCents - (inv.taxCents ?? 0));
107	  // Dedicated-IP add-on lines earn 0% commission (owner's spec) — excluded here,
108	  // not by string-matching `description`/`lineItems`, so the rule can never be
109	  // fooled by a line-item description changing later. See commissionableBaseCents.
110	  const baseCents = commissionableBaseCents(netCents, inv.dedicatedIpCents ?? 0);
111	  if (baseCents <= 0) return null;
112	  const amountCents = Math.round((baseCents * rate) / 100);
113	  if (amountCents <= 0) return null;
114	
115	  try {
116	    const row = await db.partnerCommission.create({
117	      data: {
118	        partnerId: partner.id,
119	        customerId: inv.userId,
120	        invoiceId: inv.id,
121	        baseCents,
122	        ratePct: rate,
123	        amountCents,
124	        kind: inferKind(inv.description),
125	        status: "ACCRUED",
126	      },
127	      select: { id: true, amountCents: true },
128	    });
129	    return { commissionId: row.id, amountCents: row.amountCents };
130	  } catch (e) {
131	    // Unique violation on invoiceId => another path already accrued this charge.
132	    // That is the idempotency guarantee working, not an error.
133	    if ((e as Prisma.PrismaClientKnownRequestError)?.code === "P2002") return null;
134	    throw e;
135	  }
136	}
137	
138	/**
139	 * Immediate, best-effort accrual for a customer's most recent qualifying charges.
140	 * Called inline right after a synchronous order/renewal commits so the partner
141	 * sees the commission attach at once (the sweep would otherwise catch it within a
142	 * few minutes). Scans the customer's newest PAID invoices, accruing any that lack
143	 * a commission row. Never throws — logs and moves on.
144	 */
145	export async function accrueRecentCommissionsForCustomer(
146	  customerId: string,
147	  limit = 5
148	): Promise<void> {
149	  try {
150	    // Fast exit for the overwhelmingly common case: the customer has no partner.
151	    const attached = await db.partnerCustomer.findUnique({
152	      where: { customerId },
153	      select: { id: true },
154	    });
155	    if (!attached) return;
156	
157	    const invoices = await db.invoice.findMany({
158	      where: { userId: customerId, status: "PAID", partnerCommission: null },
159	      orderBy: { createdAt: "desc" },
160	      take: limit,
161	      select: { id: true, userId: true, status: true, amountCents: true, taxCents: true, description: true, createdAt: true, dedicatedIpCents: true },
162	    });
163	    for (const inv of invoices) {
164	      await accrueCommissionForInvoice(inv);
165	    }
166	  } catch (e) {
167	    console.error("[partner-commission] inline accrual failed for", customerId, e);
168	  }
169	}
170	
171	/**
172	 * Background reconciliation sweep: accrue commission for every qualifying PAID
173	 * invoice that doesn't yet have a commission row and whose owner is attached to a
174	 * partner. This is the DURABLE hook — it covers every charge path uniformly
175	 * (initial orders, all renewals, upgrades, add-ons, domain/email/hosting/nxcloud
176	 * renewals) without each charge site needing to know about the partner program,
177	 * and it self-heals any charge the inline hooks missed. Idempotent.
178	 *
179	 * Wired into the billing worker loop (worker/index.ts) alongside billingSweep.
180	 * `sinceDays` bounds the scan so it stays cheap on each pass; anything older than
181	 * that has long since been accrued on a prior sweep.
182	 */
183	export async function reconcilePartnerCommissions(
184	  opts: { sinceDays?: number; limit?: number } = {}
185	): Promise<{ scanned: number; accrued: number }> {
186	  const sinceDays = opts.sinceDays ?? 45;
187	  const limit = opts.limit ?? 500;
188	  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60_000);
189	
190	  // Only invoices belonging to an attached customer are candidates. We join through
191	  // PartnerCustomer so partner-less customers (the vast majority) are never scanned.
192	  const invoices = await db.invoice.findMany({
193	    where: {
194	      status: "PAID",
195	      partnerCommission: null,
196	      createdAt: { gte: since },
197	      user: { partnerAttachment: { isNot: null } },
198	    },
199	    orderBy: { createdAt: "asc" },
200	    take: limit,
201	    select: { id: true, userId: true, status: true, amountCents: true, taxCents: true, description: true, createdAt: true, dedicatedIpCents: true },
202	  });
203	
204	  let accrued = 0;
205	  for (const inv of invoices) {
206	    try {
207	      const res = await accrueCommissionForInvoice(inv);
208	      if (res) accrued++;
209	    } catch (e) {
210	      // One bad invoice must never abort the sweep.
211	      console.error("[partner-commission] sweep accrual failed for invoice", inv.id, e);
212	    }
213	  }
214	  return { scanned: invoices.length, accrued };
215	}
216	
217	// ---------- Partner-facing summary ----------
218	
219	export type PartnerSummary = {
220	  partnerId: string;
221	  name: string;
222	  code: string;
223	  commissionRatePct: number;
224	  status: string;
225	  customerCount: number;
226	  /** Lifetime commission ever EARNED (every non-VOID PartnerCommission row), in cents. */
227	  lifetimeCents: number;
228	  /** lifetimeCents minus every real PartnerPayout ever recorded — the real balance owed. */
229	  outstandingCents: number;
230	  /** Sum of every real PartnerPayout ever recorded (full settlements + partial payouts). */
231	  paidCents: number;
232	};
233	
234	/**
235	 * Roll up a partner's standing: attached-customer count, lifetime commission
236	 * EARNED, and the real balance owed.
237	 *
238	 * `paidCents`/`outstandingCents` are computed from `PartnerPayout` — the ledger of
239	 * REAL payments made — not from summing PartnerCommission rows whose `status`
240	 * happens to read PAID. Two ledgers, "earned" (PartnerCommission) and "paid"
241	 * (PartnerPayout), net balance = earned − paid: the only way to honestly support
242	 * a PARTIAL payout ("$340 today even though $412 is accrued" — the owner's own
243	 * example) without inventing a way to mark a fractional set of commission rows
244	 * paid. A full settlement (adminSettlePartnerCommission) still flips every
245	 * ACCRUED row to PAID for the per-row ledger display, so for the common case the
246	 * two views agree; see PartnerPayout's own doc comment on the model.
247	 */
248	export async function computePartnerSummary(partnerId: string): Promise<PartnerSummary | null> {
249	  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
250	  if (!partner) return null;
251	
252	  const [customerCount, lifetimeAgg, payoutAgg] = await Promise.all([
253	    db.partnerCustomer.count({ where: { partnerId } }),
254	    db.partnerCommission.aggregate({
255	      where: { partnerId, status: { not: "VOID" } },
256	      _sum: { amountCents: true },
257	    }),
258	    db.partnerPayout.aggregate({
259	      where: { partnerId },
260	      _sum: { amountCents: true },
261	    }),
262	  ]);
263	
264	  const lifetimeCents = lifetimeAgg._sum.amountCents ?? 0;
265	  const paidCents = payoutAgg._sum.amountCents ?? 0;
266	  const outstandingCents = Math.max(0, lifetimeCents - paidCents);
267	  return {
268	    partnerId: partner.id,
269	    name: partner.name,
270	    code: partner.code,
271	    commissionRatePct: partner.commissionRatePct,
272	    status: partner.status,
273	    customerCount,
274	    lifetimeCents,
275	    outstandingCents,
276	    paidCents,
277	  };
278	}
279	
280	export type PartnerFunnel = {
281	  /** Rows in ReferralClick for this partner's code — real link clicks recorded by
282	   *  app/partner/[code]/route.ts (and app/r/[code]/route.ts for the legacy path). */
283	  clicked: number;
284	  /** PartnerCustomer rows — real, permanently-attached signups. */
285	  signedUp: number;
286	  /** Distinct customers with at least one PartnerCommission row — their first paid purchase. */
287	  converted: number;
288	};
289	
290	/**
291	 * Real click → signup → conversion funnel for one partner, shown on both the
292	 * partner's own dashboard and the admin detail page. Every number here is a real
293	 * count off a real table — no estimates, no placeholders (see this codebase's own
294	 * "never fabricate" rule).
295	 */
296	export async function partnerFunnel(partnerId: string, code: string): Promise<PartnerFunnel> {
297	  const [clicked, signedUp, convertedRows] = await Promise.all([
298	    db.referralClick.count({ where: { code } }),
299	    db.partnerCustomer.count({ where: { partnerId } }),
300	    db.partnerCommission.groupBy({ by: ["customerId"], where: { partnerId } }),
301	  ]);
302	  return { clicked, signedUp, converted: convertedRows.length };
303	}
304	
305	/**
306	 * Attach a customer to the partner whose `code` matches, for life. No-op if the
307	 * code doesn't map to an ACTIVE partner, or the customer is already attached to a
308	 * partner (attachment is permanent and single — the unique `customerId` also hard-
309	 * enforces this). Best-effort: returns whether an attachment was made. Intended to
310	 * be called from the registration flow when a `?ref=` code is a partner code.
311	 */
312	export async function attachCustomerToPartnerByCode(
313	  customerId: string,
314	  rawCode: string | null | undefined,
315	  // false when the code was TYPED (register page's "Creator code" field) rather
316	  // than carried in by a /partner/<code> click: there is no click to credit, and
317	  // marking an unrelated one converted would inflate the click->signup funnel.
318	  opts: { markClick?: boolean } = {},
319	): Promise<boolean> {
320	  // Partner codes are stored upper-cased (see lib/actions-partner.ts normalizeCode).
321	  const code = (rawCode ?? "").trim().toUpperCase();
322	  if (!code) return false;
323	  try {
324	    const partner = await db.referralPartner.findUnique({ where: { code } });
325	    if (!partner || partner.status !== "ACTIVE") return false;
326	    // A partner cannot self-attach (would earn commission on their own spend).
327	    if (partner.userId && partner.userId === customerId) return false;
328	    const existing = await db.partnerCustomer.findUnique({ where: { customerId } });
329	    if (existing) return false;
330	    await db.partnerCustomer.create({ data: { partnerId: partner.id, customerId } });
331	    // Best-effort: mark the click that most likely led to this signup as
332	    // converted, so the real click funnel (partnerFunnel above) can show a
333	    // clicked -> signed up rate. There's no session id carried from click to
334	    // registration (the cookie only carries the code — see app/partner/[code]/
335	    // route.ts), so this attributes to the most recent NOT-YET-CONVERTED click
336	    // for this exact code — a reasonable best match, never load-bearing for
337	    // billing (only PartnerCustomer/PartnerCommission are, and both are already
338	    // committed above/elsewhere).
339	    if (opts.markClick !== false) {
340	      try {
341	        const click = await db.referralClick.findFirst({
342	          where: { code, convertedUserId: null },
343	          orderBy: { createdAt: "desc" },
344	        });
345	        if (click) {
346	          await db.referralClick.update({ where: { id: click.id }, data: { convertedUserId: customerId } });
347	        }
348	      } catch {
349	        /* analytics-only, never blocks the real attachment above */
350	      }
351	    }
352	    return true;
353	  } catch (e) {
354	    // Unique race (two concurrent attaches) or transient error — never fatal to
355	    // the caller (registration/order must still succeed).
356	    if ((e as Prisma.PrismaClientKnownRequestError)?.code === "P2002") return false;
357	    console.error("[partner-commission] attach-by-code failed for", customerId, e);
358	    return false;
359	  }
360	}
