1	// Creator Partner Program — date-ranged analytics for the partner's own
2	// Analytics tab (/dashboard/partner?tab=analytics). Server-only.
3	//
4	// Every figure is a count or sum off a real table; nothing is estimated:
5	//   clicks      ReferralClick   (code = partner.code) — app/partner/[code]/route.ts
6	//   signups     PartnerCustomer (partnerId, attachedAt) — the permanent attachment
7	//   conversions a customer's FIRST non-void PartnerCommission — their first paid,
8	//               commissionable purchase (lib/partner-commission.ts accrues one row
9	//               per qualifying invoice)
10	//   commission  PartnerCommission rows (amountCents, status ACCRUED | PAID | VOID)
11	//   payouts     PartnerPayout rows — real off-wallet payments the admin recorded
12	//
13	// Dates are bucketed in UTC.
14	
15	import { db } from "./db";
16	import { maskEmail } from "./mask-email";
17	
18	export const RANGE_KEYS = ["7d", "30d", "90d", "12m", "all", "custom"] as const;
19	export type RangeKey = (typeof RANGE_KEYS)[number];
20	export type Bucket = "day" | "week" | "month";
21	
22	export type ResolvedRange = {
23	  key: RangeKey;
24	  from: Date; // inclusive
25	  to: Date; // exclusive
26	  bucket: Bucket;
27	  /** YYYY-MM-DD, inclusive end — for the custom picker's inputs. */
28	  fromDay: string;
29	  toDay: string;
30	  error?: string;
31	};
32	
33	const DAY = 86_400_000;
34	
35	function startOfUtcDay(d: Date): Date {
36	  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
37	}
38	function ymd(d: Date): string {
39	  return d.toISOString().slice(0, 10);
40	}
41	function parseDay(s: string | undefined): Date | null {
42	  if (!s || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
43	  const d = new Date(`${s}T00:00:00Z`);
44	  return Number.isNaN(d.getTime()) ? null : d;
45	}
46	
47	function bucketFor(spanMs: number): Bucket {
48	  const days = spanMs / DAY;
49	  if (days <= 45) return "day";
50	  if (days <= 200) return "week";
51	  return "month";
52	}
53	
54	/**
55	 * Turn `?range=&from=&to=` into a concrete [from, to) window. `earliest` is the
56	 * partner's first recorded activity, used as the start of "all time".
57	 * An unreadable custom range falls back to 30 days and says why.
58	 */
59	export function resolveRange(
60	  q: { range?: string; from?: string; to?: string },
61	  earliest: Date,
62	  now = new Date()
63	): ResolvedRange {
64	  const todayEnd = new Date(startOfUtcDay(now).getTime() + DAY);
65	  const key = (RANGE_KEYS as readonly string[]).includes(q.range ?? "") ? (q.range as RangeKey) : "30d";
66	
67	  const make = (k: RangeKey, from: Date, to: Date, error?: string): ResolvedRange => ({
68	    key: k,
69	    from,
70	    to,
71	    bucket: bucketFor(to.getTime() - from.getTime()),
72	    fromDay: ymd(from),
73	    toDay: ymd(new Date(to.getTime() - DAY)),
74	    error,
75	  });
76	  const lastDays = (n: number) => new Date(todayEnd.getTime() - n * DAY);
77	
78	  switch (key) {
79	    case "7d":
80	      return make(key, lastDays(7), todayEnd);
81	    case "90d":
82	      return make(key, lastDays(90), todayEnd);
83	    case "12m": {
84	      const f = startOfUtcDay(now);
85	      f.setUTCFullYear(f.getUTCFullYear() - 1);
86	      return make(key, new Date(f.getTime() + DAY), todayEnd);
87	    }
88	    case "all": {
89	      const f = startOfUtcDay(earliest);
90	      // At least a week, so a brand-new partner's chart isn't a single bar.
91	      return make(key, f.getTime() > lastDays(7).getTime() ? lastDays(7) : f, todayEnd);
92	    }
93	    case "custom": {
94	      const f = parseDay(q.from);
95	      const t = parseDay(q.to);
96	      if (!f || !t) return make("30d", lastDays(30), todayEnd, "Pick both a start and an end date.");
97	      if (f.getTime() > t.getTime()) return make("30d", lastDays(30), todayEnd, "The start date is after the end date.");
98	      const end = new Date(Math.min(t.getTime() + DAY, todayEnd.getTime()));
99	      if (end.getTime() - f.getTime() > 5 * 366 * DAY) return make("30d", lastDays(30), todayEnd, "Custom ranges can span at most five years.");
100	      if (f.getTime() >= todayEnd.getTime()) return make("30d", lastDays(30), todayEnd, "That range is in the future.");
101	      return make("custom", f, end);
102	    }
103	    default:
104	      return make("30d", lastDays(30), todayEnd);
105	  }
106	}
107	
108	function bucketStart(d: Date, b: Bucket): Date {
109	  const day = startOfUtcDay(d);
110	  if (b === "day") return day;
111	  if (b === "week") {
112	    const dow = (day.getUTCDay() + 6) % 7; // Monday = 0
113	    return new Date(day.getTime() - dow * DAY);
114	  }
115	  return new Date(Date.UTC(day.getUTCFullYear(), day.getUTCMonth(), 1));
116	}
117	function nextBucket(d: Date, b: Bucket): Date {
118	  if (b === "day") return new Date(d.getTime() + DAY);
119	  if (b === "week") return new Date(d.getTime() + 7 * DAY);
120	  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 1));
121	}
122	
123	/** Every bucket start covering [from, to), in order. */
124	function bucketKeys(r: ResolvedRange): Date[] {
125	  const out: Date[] = [];
126	  for (let d = bucketStart(r.from, r.bucket); d.getTime() < r.to.getTime(); d = nextBucket(d, r.bucket)) {
127	    out.push(d);
128	    if (out.length > 400) break; // hard stop — month buckets over 5y is 61
129	  }
130	  return out;
131	}
132	
133	/**
134	 * A product LABEL for a commission row, derived from the invoice description
135	 * WITHOUT exposing the customer's own identifiers. Descriptions carry server
136	 * hostnames and domains ("Pro VPS (studionexis-soul) — Monthly", "Business
137	 * Email renewal: Starter for example.com") — a partner sees the kind of
138	 * product, never their customer's server or domain name.
139	 */
140	export function productLabel(description: string): string {
141	  const d = description.replace(/^renewal:\s*/i, "").trim();
142	  const low = d.toLowerCase();
143	  if (low.includes("game server") || /\b(slots|players)\b/.test(low)) {
144	    const game = d.split(/\s+—\s+/)[0]?.trim();
145	    return game && game.length <= 40 ? `Game server · ${game}` : "Game server";
146	  }
147	  if (low.includes("business email") || low.includes("mailbox")) return "Business email";
148	  if (low.includes("domain")) return "Domain";
149	  if (low.includes("hosting")) return "Web hosting";
150	  if (low.includes("extra disk") || low.includes("storage")) return "Extra storage";
151	  if (low.includes("backup")) return "Backups";
152	  if (low.includes("dedicated ip")) return "Dedicated IP";
153	  if (low.includes("vps") || low.includes("vcpu")) {
154	    const plan = d.split(/\s*\(/)[0]?.trim();
155	    return plan && plan.length <= 40 && /vps/i.test(plan) ? plan : "VPS";
156	  }
157	  return "Other service";
158	}
