219	export async function computePartnerAnalytics(
220	  partner: { id: string; code: string },
221	  r: ResolvedRange
222	): Promise<PartnerAnalytics> {
223	  const inRange = { gte: r.from, lt: r.to };
224	  const [clicks, signups, firstCommissions, commissionRows, statusSums, payouts, events] = await Promise.all([
225	    db.referralClick.findMany({
226	      where: { code: partner.code, createdAt: inRange },
227	      select: { createdAt: true, referer: true, convertedUserId: true },
228	      take: 100_000,
229	    }),
230	    db.partnerCustomer.findMany({
231	      where: { partnerId: partner.id, attachedAt: inRange },
232	      select: { attachedAt: true, customerId: true },
233	    }),
234	    // Each attached customer's first non-void commission = their first paid purchase.
235	    db.partnerCommission.groupBy({
236	      by: ["customerId"],
237	      where: { partnerId: partner.id, status: { not: "VOID" } },
238	      _min: { createdAt: true },
239	    }),
240	    db.partnerCommission.findMany({
241	      where: { partnerId: partner.id, createdAt: inRange, status: { not: "VOID" } },
242	      select: { createdAt: true, amountCents: true },
243	    }),
244	    db.partnerCommission.groupBy({
245	      by: ["status"],
246	      where: { partnerId: partner.id, createdAt: inRange },
247	      _sum: { amountCents: true },
248	      _count: { _all: true },
249	    }),
250	    db.partnerPayout.aggregate({ where: { partnerId: partner.id, createdAt: inRange }, _sum: { amountCents: true } }),
251	    db.partnerCommission.findMany({
252	      where: { partnerId: partner.id, createdAt: inRange },
253	      orderBy: { createdAt: "desc" },
254	      take: EVENTS_LIMIT + 1,
255	      select: {
256	        id: true,
257	        createdAt: true,
258	        kind: true,
259	        baseCents: true,
260	        amountCents: true,
261	        status: true,
262	        customer: { select: { name: true, email: true } },
263	        invoice: { select: { description: true } },
264	      },
265	    }),
266	  ]);
267	
268	  const conversionsInRange = firstCommissions
269	    .map((c) => c._min.createdAt)
270	    .filter((d): d is Date => !!d && d >= r.from && d < r.to);
271	  const paidCustomers = new Set(firstCommissions.map((c) => c.customerId));
272	
273	  // ---- time series ----
274	  const keys = bucketKeys(r);
275	  const idx = new Map(keys.map((k, i) => [k.getTime(), i]));
276	  const series: SeriesPoint[] = keys.map((k) => ({
277	    t: k.toISOString(),
278	    label: label(k, r.bucket),
279	    clicks: 0,
280	    signups: 0,
281	    conversions: 0,
282	    commissionCents: 0,
283	  }));
284	  const at = (d: Date) => idx.get(bucketStart(d, r.bucket).getTime());
285	  for (const c of clicks) { const i = at(c.createdAt); if (i !== undefined) series[i].clicks++; }
286	  for (const s of signups) { const i = at(s.attachedAt); if (i !== undefined) series[i].signups++; }
287	  for (const d of conversionsInRange) { const i = at(d); if (i !== undefined) series[i].conversions++; }
288	  for (const c of commissionRows) { const i = at(c.createdAt); if (i !== undefined) series[i].commissionCents += c.amountCents; }
289	
290	  // ---- sources (referer host) ----
291	  const src = new Map<string, { clicks: number; signups: number }>();
292	  for (const c of clicks) {
293	    const k = sourceOf(c.referer);
294	    const e = src.get(k) ?? { clicks: 0, signups: 0 };
295	    e.clicks++;
296	    if (c.convertedUserId) e.signups++;
297	    src.set(k, e);
298	  }
299	  const sources = [...src.entries()]
300	    .map(([source, v]) => ({ source, ...v }))
301	    .sort((a, b) => b.clicks - a.clicks)
302	    .slice(0, 10);
303	
304	  const sum = (status: string) => statusSums.find((s) => s.status === status)?._sum.amountCents ?? 0;
305	  const accruedCents = sum("ACCRUED");
306	  const paidRowCents = sum("PAID");
307	
308	  return {
309	    range: { ...r, from: r.from.toISOString(), to: r.to.toISOString() },
310	    totals: {
311	      clicks: clicks.length,
312	      clicksLedToSignup: clicks.filter((c) => c.convertedUserId).length,
313	      signups: signups.length,
314	      conversions: conversionsInRange.length,
315	      signupsInRangeWhoPaid: signups.filter((s) => paidCustomers.has(s.customerId)).length,
316	      commissionCents: accruedCents + paidRowCents,
317	      accruedCents,
318	      paidRowCents,
319	      voidCents: sum("VOID"),
320	      payoutsCents: payouts._sum.amountCents ?? 0,
321	      charges: statusSums.filter((s) => s.status !== "VOID").reduce((n, s) => n + s._count._all, 0),
322	    },
323	    series,
324	    sources,
325	    events: events.slice(0, EVENTS_LIMIT).map((e) => ({
326	      id: e.id,
327	      when: e.createdAt.toISOString(),
328	      // Same identifier the page has always shown for a commission row, but a
329	      // name-less customer's email is MASKED (lib/mask-email.ts) — this feeds
330	      // the PARTNER's own dashboard, and customers never agreed to be shown to
331	      // a creator. Admin views don't use this module.
332	      customer: e.customer.name || maskEmail(e.customer.email),
333	      product: productLabel(e.invoice.description),
334	      kind: e.kind,
335	      baseCents: e.baseCents,
336	      amountCents: e.amountCents,
337	      status: e.status,
338	    })),
339	    eventsTruncated: events.length > EVENTS_LIMIT,
340	  };
341	}
