    db.invoice.findMany({
      where: { userId: { in: userIds }, status: { in: ["PAID", "REFUNDED"] } },
      select: { userId: true, description: true, amountCents: true, refundedCents: true, status: true },
    }),
    db.walletTransaction.findMany({
      where: {
        userId: { in: userIds },
        OR: [
          { description: { startsWith: "Downgrade to" } },
          { description: { startsWith: "Refund: failed" } },
          { description: { startsWith: "Reversed downgrade credit" } },
