import { requireArea } from "@/lib/rbac";
import { PageHeader, StatCard, Badge } from "@/components/ui/primitives";
import { MeterBar } from "@/components/ui/charts";
import { signupRetentionRows, summarizeRetention, weeklyCohorts } from "@/lib/retention";

export const dynamic = "force-dynamic";

function pct(n: number, d: number): string {
  if (d <= 0) return "—";
  return `${Math.round((n / d) * 100)}%`;
}

function fmtDate(d: Date): string {
  return d.toISOString().slice(0, 10);
}

export default async function RetentionPage() {
  await requireArea("analytics");

  const rows = await signupRetentionRows();
  const summary = summarizeRetention(rows);
  const cohorts = weeklyCohorts(rows);
  const cohortMax = Math.max(...cohorts.map((c) => c.size), 1);

  // Newest signups first for the account table.
  const sorted = [...rows].sort((a, b) => b.signup.getTime() - a.signup.getTime());

  return (
    <div className="space-y-6">
      <PageHeader
        title="Account retention"
        sub="Of the people who create a Nxeon account, how many come back? Counts any activity — a portal visit, a server, a ticket, a wallet transaction — after the signup day, not just marketing pageviews."
      />

      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
        <StatCard label="Real customer accounts" value={String(summary.total)} delta="excludes staff/sandbox/admin" />
        <StatCard
          label="Returned after 1 day"
          value={pct(summary.returned1d, summary.eligible1d)}
          delta={summary.eligible1d > 0 ? `${summary.returned1d} of ${summary.eligible1d} eligible` : "no accounts old enough yet"}
          deltaGood={summary.eligible1d > 0 && summary.returned1d / summary.eligible1d >= 0.3}
        />
        <StatCard
          label="Returned after 7 days"
          value={pct(summary.returned7d, summary.eligible7d)}
          delta={summary.eligible7d > 0 ? `${summary.returned7d} of ${summary.eligible7d} eligible` : "no accounts old enough yet"}
          deltaGood={summary.eligible7d > 0 && summary.returned7d / summary.eligible7d >= 0.2}
        />
        <StatCard
          label="Returned after 30 days"
          value={pct(summary.returned30d, summary.eligible30d)}
          delta={summary.eligible30d > 0 ? `${summary.returned30d} of ${summary.eligible30d} eligible` : "no accounts old enough yet"}
          deltaGood={summary.eligible30d > 0 && summary.returned30d / summary.eligible30d >= 0.15}
        />
      </div>

      <div className="card">
        <h2 className="mb-1 font-semibold">Weekly signup cohorts</h2>
        <p className="mb-4 text-xs text-slate-500">
          Signups grouped by the Monday of their signup week · share that returned within 7 days. Only cohorts old
          enough to judge (signed up 7+ days ago) are shown.
        </p>
        {cohorts.length === 0 ? (
          <p className="py-8 text-center text-sm text-slate-500">No cohort is old enough to judge yet.</p>
        ) : (
          <div className="space-y-3">
            {cohorts.map((c) => (
              <div key={c.weekStart.toISOString()}>
                <div className="mb-1 flex items-baseline justify-between text-sm">
                  <span className="font-medium">Week of {fmtDate(c.weekStart)}</span>
                  <span className="tabular-nums">
                    <span className="font-semibold">{c.size}</span>
                    <span className="ml-2 text-xs text-slate-500">
                      signups · {pct(c.returned7d, c.size)} returned by day 7
                    </span>
                  </span>
                </div>
                <MeterBar value={c.size} max={cohortMax} color="#8a70fb" />
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="card overflow-x-auto p-0">
        <table className="table-shell">
          <thead>
            <tr>
              <th>Signed up</th>
              <th>Email</th>
              <th>Days ago</th>
              <th>Last activity</th>
              <th>Returned?</th>
            </tr>
          </thead>
          <tbody>
            {sorted.map((r) => (
              <tr key={r.id}>
                <td className="whitespace-nowrap text-slate-400">{fmtDate(r.signup)}</td>
                <td className="whitespace-nowrap">{r.email}</td>
                <td className="tabular-nums text-slate-400">{r.daysSinceSignup}d</td>
                <td className="whitespace-nowrap text-slate-400">
                  {r.lastActivity ? fmtDate(r.lastActivity) : <span className="text-slate-600">signup only</span>}
                </td>
                <td>
                  {r.daysSinceSignup < 1 ? (
                    <span className="text-slate-600">too new to judge</span>
                  ) : r.returned30d ? (
                    <Badge tone="green">returned</Badge>
                  ) : r.returned7d ? (
                    <Badge tone="brand">returned (7d+)</Badge>
                  ) : r.returned1d ? (
                    <Badge tone="amber">returned (1d+)</Badge>
                  ) : (
                    <Badge tone="slate">never came back</Badge>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
