import { useEffect, useRef, useState } from "react";

export type BarDatum = { label: string; value: number; /** Tooltip heading; defaults to label. */ title?: string };

function niceMax(max: number, integer: boolean): { top: number; step: number } {
  if (max <= 0) return { top: integer ? 4 : 1, step: integer ? 1 : 0.25 };
  const rough = max / 4;
  const pow = Math.pow(10, Math.floor(Math.log10(rough)));
  const n = rough / pow;
  let step = (n <= 1 ? 1 : n <= 2 ? 2 : n <= 2.5 ? 2.5 : n <= 5 ? 5 : 10) * pow;
  if (integer) step = Math.max(1, Math.ceil(step));
  return { top: step * Math.ceil(max / step), step };
}

export function BarChart({
