    existingAccounts: number;
    attachedViaMatchedClick: number;
    /** Of the customers attached in range, how many have made a paid purchase since (any date up to now). */
    cohortPaid: number;
    firstPurchases: number;
    charges: number;
    revenueCents: number;
    commissionCents: number;
    payoutsCents: number;
  };
  /** All time, not range-bound. */
  ledger: { earnedCents: number; paidOutCents: number; owedCents: number; accruedRowCents: number };
  series: ProgramSeriesPoint[];
  rows: ProgramPartnerRow[];
  products: { label: string; revenueCents: number; charges: number }[];
  sources: { source: string; clicks: number }[];
  invites: {
    total: number;
    drafts: number;
    outstanding: number;
    accepted: number;
    expired: number;
    revoked: number;
    /** Accepted creator invites whose partner link has at least one recorded click. */
    claimedWithClick: number;
  };
};

type Query = { range?: string; from?: string; to?: string; hide?: string | string[] };

export async function computeProgramAnalytics(q: Query, now = new Date()): Promise<ProgramAnalytics> {
  const allPartners = await db.referralPartner.findMany({
    orderBy: { createdAt: "asc" },
    take: 5000,
    select: { id: true, name: true, code: true, status: true, commissionRatePct: true, createdAt: true },
  });
  const hideSet = new Set((Array.isArray(q.hide) ? q.hide : q.hide ? [q.hide] : []).filter(Boolean));
  const partners = allPartners.filter((p) => !hideSet.has(p.id));
  const hiddenIds = allPartners.filter((p) => hideSet.has(p.id)).map((p) => p.id);
  const ids = partners.map((p) => p.id);
  const codes = partners.map((p) => p.code);
  const allCodes = allPartners.map((p) => p.code);
  const byId = new Map(partners.map((p) => [p.id, p]));
  const idByCode = new Map(partners.map((p) => [p.code, p.id]));

  // "All time" starts at the earliest real activity among the included partners.
  const [clickCountsAll, firstAttach] = await Promise.all([
    db.referralClick.groupBy({
      by: ["code"],
      where: { code: { in: allCodes } },
      _count: { _all: true },
      _min: { createdAt: true },
    }),
    db.partnerCustomer.findFirst({
      where: { partnerId: { in: ids } },
      orderBy: { attachedAt: "asc" },
      select: { attachedAt: true },
    }),
  ]);
  const clicksAllByCode = new Map(clickCountsAll.map((c) => [c.code, c._count._all]));
  const earliest = new Date(
    Math.min(
      now.getTime(),
      ...partners.map((p) => p.createdAt.getTime()),
      ...clickCountsAll.filter((c) => idByCode.has(c.code)).map((c) => c._min.createdAt?.getTime() ?? Infinity),
      firstAttach?.attachedAt.getTime() ?? Infinity
    )
  );
  // The program is young, so the admin view opens on "all time" rather than 30 days.
  const r = resolveRange({ range: q.range ?? "all", from: q.from, to: q.to }, earliest, now);
  const inRange = { gte: r.from, lt: r.to };

  const [
    clicks,
    matchedClicks,
    otherCodeClicks,
    attachments,
    invoices,
    commissionRows,
    commissionByPartner,
    commissionBefore,
    payoutRows,
    payoutsByPartner,
    payoutsBefore,
    invites,
  ] = await Promise.all([
    db.referralClick.findMany({
      where: { code: { in: codes }, createdAt: inRange },
      select: { code: true, createdAt: true, ipHash: true, referer: true, convertedUserId: true },
      take: CLICK_ROW_CAP + 1,
    }),
    // Every click (any date) that was matched to a signup — to tell which attached
    // customers came through a tracked link visit.
    db.referralClick.findMany({
      where: { code: { in: codes }, convertedUserId: { not: null } },
      select: { code: true, convertedUserId: true },
    }),
    db.referralClick.count({ where: { code: { notIn: allCodes }, createdAt: inRange } }),
    db.partnerCustomer.findMany({
      where: { partnerId: { in: ids } },
      select: { partnerId: true, customerId: true, attachedAt: true, createdAt: true, customer: { select: { createdAt: true } } },
    }),
    // All-time: a customer's FIRST paid purchase may predate the range.
    db.invoice.findMany({
      where: {
        status: "PAID",
        amountCents: { gt: 0 },
        user: { partnerAttachment: { is: { partnerId: { in: ids } } } },
      },
      select: {
        id: true,
        userId: true,
        status: true,
        amountCents: true,
        taxCents: true,
        description: true,
        createdAt: true,
        dedicatedIpCents: true,
      },
    }),
    db.partnerCommission.findMany({
      where: { partnerId: { in: ids }, createdAt: inRange, status: { not: "VOID" } },
      select: { partnerId: true, createdAt: true, amountCents: true },
    }),
    db.partnerCommission.groupBy({
      by: ["partnerId", "status"],
      where: { partnerId: { in: ids } },
      _sum: { amountCents: true },
    }),
    db.partnerCommission.aggregate({
      where: { partnerId: { in: ids }, status: { not: "VOID" }, createdAt: { lt: r.from } },
      _sum: { amountCents: true },
    }),
    db.partnerPayout.findMany({
      where: { partnerId: { in: ids }, createdAt: inRange },
      select: { partnerId: true, createdAt: true, amountCents: true },
    }),
    db.partnerPayout.groupBy({ by: ["partnerId"], where: { partnerId: { in: ids } }, _sum: { amountCents: true } }),
    db.partnerPayout.aggregate({
      where: { partnerId: { in: ids }, createdAt: { lt: r.from } },
      _sum: { amountCents: true },
    }),
    db.partnerInvite.findMany({
      where: { kind: "CREATOR" },
      select: { acceptedAt: true, revokedAt: true, lastSentAt: true, expiresAt: true, partnerId: true },
    }),
  ]);

  const clicksTruncated = clicks.length > CLICK_ROW_CAP;
  if (clicksTruncated) clicks.length = CLICK_ROW_CAP;
  const within = (d: Date) => d >= r.from && d < r.to;

  // ---- attribution: qualifying invoices, first purchases ----
  const attachByCustomer = new Map(attachments.map((a) => [a.customerId, a]));
  const qualifying = invoices.filter((inv) => {
    const a = attachByCustomer.get(inv.userId);
    // Same future-only rule as accrueCommissionForInvoice: only charges at/after attachment.
    return !!a && inv.createdAt >= a.createdAt && isCommissionableInvoice(inv);
  });
  const firstPurchaseAt = new Map<string, Date>();
  for (const inv of qualifying) {
    const cur = firstPurchaseAt.get(inv.userId);
    if (!cur || inv.createdAt < cur) firstPurchaseAt.set(inv.userId, inv.createdAt);
  }
  const matchedCustomer = new Set(
    matchedClicks
      .filter((c) => c.convertedUserId && attachByCustomer.get(c.convertedUserId)?.partnerId === idByCode.get(c.code))
      .map((c) => c.convertedUserId as string)
  );

  // ---- per-partner accumulators ----
  type Acc = Omit<ProgramPartnerRow, "id" | "name" | "code" | "status" | "ratePct"> & { ips: Set<string> };
  const acc = new Map<string, Acc>(
    partners.map((p) => [
      p.id,
      {
        clicks: 0,
        uniqueVisitors: 0,
        newCustomers: 0,
        firstPurchases: 0,
        revenueCents: 0,
        commissionCents: 0,
        customersTotal: 0,
        clicksAllTime: clicksAllByCode.get(p.code) ?? 0,
        lifetimeEarnedCents: 0,
        paidOutCents: 0,
        owedCents: 0,
        ips: new Set<string>(),
      },
    ])
  );

  // ---- time series ----
  const keys = bucketKeys(r);
  const idx = new Map(keys.map((k, i) => [k.getTime(), i]));
  const series: ProgramSeriesPoint[] = keys.map((k) => ({
    t: k.toISOString(),
    label: bucketLabel(k, r.bucket),
    clicks: 0,
    newCustomers: 0,
    firstPurchases: 0,
    revenueCents: 0,
    commissionCents: 0,
    payoutsCents: 0,
    cumEarnedCents: 0,
    cumPaidCents: 0,
  }));
  const at = (d: Date) => idx.get(bucketStart(d, r.bucket).getTime());

  // Clicks
  const ipsAll = new Set<string>();
  let clicksWithoutIp = 0;
  let clicksMatched = 0;
  const src = new Map<string, number>();
  for (const c of clicks) {
    const pid = idByCode.get(c.code);
    const a = pid ? acc.get(pid) : undefined;
    if (a) {
      a.clicks++;
      if (c.ipHash) a.ips.add(c.ipHash);
    }
    if (c.ipHash) ipsAll.add(c.ipHash);
    else clicksWithoutIp++;
    if (c.convertedUserId) clicksMatched++;
    const i = at(c.createdAt);
    if (i !== undefined) series[i].clicks++;
    const s = sourceOf(c.referer);
    src.set(s, (src.get(s) ?? 0) + 1);
  }

  // Attachments
  let newCustomers = 0;
  let newAccounts = 0;
  let attachedViaMatchedClick = 0;
  let cohortPaid = 0;
  for (const a of attachments) {
    const pa = acc.get(a.partnerId);
    if (pa) pa.customersTotal++;
    if (!within(a.attachedAt)) continue;
    newCustomers++;
    if (pa) pa.newCustomers++;
    if (a.attachedAt.getTime() - a.customer.createdAt.getTime() <= NEW_ACCOUNT_WINDOW_MS) newAccounts++;
    if (matchedCustomer.has(a.customerId)) attachedViaMatchedClick++;
    if (firstPurchaseAt.has(a.customerId)) cohortPaid++;
    const i = at(a.attachedAt);
    if (i !== undefined) series[i].newCustomers++;
  }

  // First purchases in range
  let firstPurchases = 0;
  for (const [customerId, d] of firstPurchaseAt) {
    if (!within(d)) continue;
    firstPurchases++;
    const pid = attachByCustomer.get(customerId)?.partnerId;
    const pa = pid ? acc.get(pid) : undefined;
    if (pa) pa.firstPurchases++;
    const i = at(d);
    if (i !== undefined) series[i].firstPurchases++;
  }

  // Referred revenue in range (+ product mix)
  let revenueCents = 0;
  let charges = 0;
  const prod = new Map<string, { revenueCents: number; charges: number }>();
  for (const inv of qualifying) {
    if (!within(inv.createdAt)) continue;
    const net = Math.max(0, inv.amountCents - (inv.taxCents ?? 0));
    revenueCents += net;
    charges++;
    const pid = attachByCustomer.get(inv.userId)?.partnerId;
    const pa = pid ? acc.get(pid) : undefined;
    if (pa) pa.revenueCents += net;
    const i = at(inv.createdAt);
    if (i !== undefined) series[i].revenueCents += net;
    const label = productLabel(inv.description);
    const e = prod.get(label) ?? { revenueCents: 0, charges: 0 };
    e.revenueCents += net;
    e.charges++;
    prod.set(label, e);
  }

  // Commission + payouts in range
  let commissionCents = 0;
  for (const c of commissionRows) {
    commissionCents += c.amountCents;
    const pa = acc.get(c.partnerId);
    if (pa) pa.commissionCents += c.amountCents;
    const i = at(c.createdAt);
    if (i !== undefined) series[i].commissionCents += c.amountCents;
  }
  let payoutsCents = 0;
  for (const p of payoutRows) {
    payoutsCents += p.amountCents;
    const i = at(p.createdAt);
    if (i !== undefined) series[i].payoutsCents += p.amountCents;
  }
  let runEarned = commissionBefore._sum.amountCents ?? 0;
  let runPaid = payoutsBefore._sum.amountCents ?? 0;
  for (const pt of series) {
    runEarned += pt.commissionCents;
    runPaid += pt.payoutsCents;
    pt.cumEarnedCents = runEarned;
    pt.cumPaidCents = runPaid;
  }

  // ---- all-time ledger ----
  let accruedRowCents = 0;
  for (const g of commissionByPartner) {
    const cents = g._sum.amountCents ?? 0;
    if (g.status === "ACCRUED") accruedRowCents += cents;
    if (g.status === "VOID") continue;
    const pa = acc.get(g.partnerId);
    if (pa) pa.lifetimeEarnedCents += cents;
  }
  for (const g of payoutsByPartner) {
    const pa = acc.get(g.partnerId);
    if (pa) pa.paidOutCents += g._sum.amountCents ?? 0;
  }
  let earnedCents = 0;
  let paidOutCents = 0;
  let owedCents = 0;
  for (const a of acc.values()) {
    a.uniqueVisitors = a.ips.size;
    a.owedCents = Math.max(0, a.lifetimeEarnedCents - a.paidOutCents);
    earnedCents += a.lifetimeEarnedCents;
    paidOutCents += a.paidOutCents;
    owedCents += a.owedCents;
  }

  const rows: ProgramPartnerRow[] = partners
    .map((p) => {
      const { ips: _ips, ...a } = acc.get(p.id)!;
      return { id: p.id, name: p.name, code: p.code, status: p.status, ratePct: p.commissionRatePct, ...a };
    })
    .sort(
      (x, y) =>
        y.revenueCents - x.revenueCents ||
        y.commissionCents - x.commissionCents ||
        y.newCustomers - x.newCustomers ||
        y.clicks - x.clicks ||
        x.name.localeCompare(y.name)
    );

  // ---- creator recruitment (all creator invites, all time) ----
  const inv = { total: invites.length, drafts: 0, outstanding: 0, accepted: 0, expired: 0, revoked: 0, claimedWithClick: 0 };
  for (const i of invites) {
    const st = creatorInviteState(i, now);
    if (st === "draft") inv.drafts++;
    else if (st === "sent") inv.outstanding++;
    else if (st === "accepted") {
      inv.accepted++;
      const code = i.partnerId ? allPartners.find((p) => p.id === i.partnerId)?.code : undefined;
      if (code && (clicksAllByCode.get(code) ?? 0) > 0) inv.claimedWithClick++;
    } else if (st === "expired") inv.expired++;
    else if (st === "revoked") inv.revoked++;
  }

  return {
    range: { ...r, from: r.from.toISOString(), to: r.to.toISOString() },
    allPartners: allPartners.map((p) => ({ id: p.id, name: p.name, code: p.code })),
    hiddenIds,
    partners: {
      total: partners.length,
      active: partners.filter((p) => p.status === "ACTIVE").length,
      withClicksEver: rows.filter((x) => x.clicksAllTime > 0).length,
      withCustomers: rows.filter((x) => x.customersTotal > 0).length,
      earning: rows.filter((x) => x.lifetimeEarnedCents > 0).length,
    },
    totals: {
      clicks: clicks.length,
      uniqueVisitors: ipsAll.size,
      clicksWithoutIp,
      clicksMatched,
      clicksTruncated,
      otherCodeClicks,
      newCustomers,
      newAccounts,
      existingAccounts: newCustomers - newAccounts,
      attachedViaMatchedClick,
      cohortPaid,
      firstPurchases,
      charges,
      revenueCents,
      commissionCents,
      payoutsCents,
    },
    ledger: { earnedCents, paidOutCents, owedCents, accruedRowCents },
    series,
    rows,
    products: [...prod.entries()]
      .map(([label, v]) => ({ label, ...v }))
      .sort((a, b) => b.revenueCents - a.revenueCents)
      .slice(0, 8),
    sources: [...src.entries()]
      .map(([source, n]) => ({ source, clicks: n }))
      .sort((a, b) => b.clicks - a.clicks)
      .slice(0, 8),
    invites: inv,
  };
}

