import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { PageHeader, StatCard, Badge } from "@/components/ui/primitives";
import { AreaChart, MeterBar } from "@/components/ui/charts";
import { formatMoney, currentCurrency } from "@/lib/tax";
import { computeProgramAnalytics, type ProgramSeriesPoint } from "@/lib/partner-program-analytics";

export const dynamic = "force-dynamic";

// Program-wide Creator Partner analytics — every partner combined. All figures
// come from lib/partner-program-analytics.ts, which documents the exact table
// and rule behind each one; this page only lays them out.

const RANGES: { key: string; label: string }[] = [
  { key: "7d", label: "7d" },
  { key: "30d", label: "30d" },
  { key: "90d", label: "90d" },
  { key: "12m", label: "12m" },
  { key: "all", label: "All time" },
];

const C = {
  clicks: "#22d3ee",
  customers: "#3b82f6",
  paying: "#34d399",
  revenue: "#34d399",
  commission: "#8a70fb",
  earned: "#fbbf24",
  paid: "#34d399",
};

function pct(n: number, d: number): string {
  if (d <= 0) return "—";
  const v = (n / d) * 100;
  return `${v >= 10 || v === 0 ? Math.round(v) : v.toFixed(1)}%`;
}

function plural(n: number, one: string, many = `${one}s`): string {
  return `${n.toLocaleString("en-US")} ${n === 1 ? one : many}`;
}

/** A top-of-axis value that splits into 4 round steps (AreaChart draws 4 gridlines). */
function niceMax(max: number, integer: boolean): number {
  if (max <= 0) return integer ? 4 : 400;
  const rough = max / 4;
  const pow = Math.pow(10, Math.floor(Math.log10(rough)));
  const n = rough / pow;
  let step = (n <= 1 ? 1 : n <= 2 ? 2 : n <= 2.5 ? 2.5 : n <= 5 ? 5 : 10) * pow;
  if (integer) step = Math.max(1, Math.ceil(step));
  return step * 4;
}

/** At most ~6 evenly spaced x labels — AreaChart spreads whatever it is given across the full width. */
function xLabelsFor(series: ProgramSeriesPoint[]): string[] {
  const n = series.length;
  if (n <= 6) return series.map((p) => p.label);
  const m = 6;
  return Array.from({ length: m }, (_, i) => series[Math.round((i * (n - 1)) / (m - 1))].label);
}

function bucketTitle(iso: string, bucket: string): string {
  const d = new Date(iso);
  if (bucket === "month") return d.toLocaleDateString("en-US", { month: "long", year: "numeric", timeZone: "UTC" });
  const day = d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" });
  return bucket === "week" ? `Week of ${day}` : day;
}

function fmtDay(ymd: string): string {
  return new Date(`${ymd}T00:00:00Z`).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" });
}

function Legend({ items }: { items: { label: string; color: string }[] }) {
  return (
    <div className="mb-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-slate-400">
      {items.map((i) => (
        <span key={i.label} className="inline-flex items-center gap-1.5">
          <span className="h-2 w-2 rounded-full" style={{ background: i.color }} />
          {i.label}
        </span>
      ))}
    </div>
  );
}

function NoData({ children }: { children: React.ReactNode }) {
  return <p className="py-10 text-center text-sm text-slate-500">{children}</p>;
}

export default async function PartnerProgramAnalyticsPage({
  searchParams,
}: {
  searchParams: Promise<{ range?: string; from?: string; to?: string; hide?: string | string[] }>;
}) {
  await requireArea("billing");
  const sp = await searchParams;
  const [data, currency] = await Promise.all([computeProgramAnalytics(sp), currentCurrency()]);
  const money = (c: number) => formatMoney(c, currency);
  const t = data.totals;
  const r = data.range;
  const bucketWord = r.bucket;
  const hidden = new Set(data.hiddenIds);

  const href = (params: Record<string, string>) => {
    const qs = new URLSearchParams(params);
    for (const id of data.hiddenIds) qs.append("hide", id);
    const s = qs.toString();
    return `/admin/partners/analytics${s ? `?${s}` : ""}`;
  };

  const s = data.series;
  const xLabels = xLabelsFor(s);
  const chartable = s.length >= 2;
  const countMax = (vals: number[]) => niceMax(Math.max(0, ...vals), true);
  const moneyMax = (vals: number[]) => niceMax(Math.max(0, ...vals), false);
  const hasClicks = t.clicks > 0;
  const hasCustomers = t.newCustomers + t.firstPurchases > 0;
  const hasMoney = t.revenueCents + t.commissionCents > 0;
  const hasLedger = s.some((p) => p.cumEarnedCents + p.cumPaidCents > 0);
  const revenueMax = Math.max(1, ...data.rows.map((x) => x.revenueCents));

  const funnel = [
    {
      label: "Link clicks",
      value: t.clicks,
      note: `${plural(t.uniqueVisitors, "unique visitor")}${t.clicksWithoutIp ? ` · ${t.clicksWithoutIp} without an IP` : ""}`,
    },
    {
      label: "Clicks matched to a signup",
      value: t.clicksMatched,
      note: `${pct(t.clicksMatched, t.clicks)} of clicks`,
    },
    {
      label: "Customers attached",
      value: t.newCustomers,
      note: `${t.newAccounts} new ${t.newAccounts === 1 ? "account" : "accounts"} · ${t.existingAccounts} existing · ${t.attachedViaMatchedClick} via a matched click`,
    },
    {
      label: "…of whom have paid",
      value: t.cohortPaid,
      note: `${pct(t.cohortPaid, t.newCustomers)} of attached customers`,
    },
  ];
  const funnelMax = Math.max(1, ...funnel.map((f) => f.value));

  return (
    <div className="space-y-6">
      <PageHeader
        title="Partner program analytics"
        sub="Every partner combined — link clicks, attributed customers, referred revenue and commission, read from the real ledgers. Nothing here is estimated."
      />

      {/* Range + partner filter */}
      <div className="card space-y-3">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="flex flex-wrap gap-2">
            {RANGES.map((x) => (
              <Link
                key={x.key}
                href={href({ range: x.key })}
                className={`rounded-lg border px-3 py-1.5 text-sm ${
                  r.key === x.key
                    ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
                    : "border-white/[0.08] text-slate-400 hover:text-slate-200"
                }`}
              >
                {x.label}
              </Link>
            ))}
          </div>
          <p className="text-xs text-slate-500">
            {fmtDay(r.fromDay)} – {fmtDay(r.toDay)} · UTC · per {bucketWord}
          </p>
        </div>
        <form method="GET" action="/admin/partners/analytics" className="flex flex-wrap items-end gap-3 border-t border-white/[0.06] pt-3">
          <input type="hidden" name="range" value="custom" />
          {data.hiddenIds.map((id) => (
            <input key={id} type="hidden" name="hide" value={id} />
          ))}
          <div>
            <label className="label">From</label>
            <input className="input py-1.5" type="date" name="from" defaultValue={r.fromDay} required />
          </div>
          <div>
            <label className="label">To</label>
            <input className="input py-1.5" type="date" name="to" defaultValue={r.toDay} required />
          </div>
          <button className={`btn-ghost ${r.key === "custom" ? "text-brand-200" : ""}`}>Apply custom range</button>
        </form>
        {r.error && (
          <p className="rounded-lg border border-amber-500/35 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
            {r.error} Showing the last 30 days instead.
          </p>
        )}
        {data.allPartners.length > 0 && (
          <details className="border-t border-white/[0.06] pt-3" open={data.hiddenIds.length > 0}>
            <summary className="cursor-pointer select-none text-sm text-slate-400 hover:text-slate-200">
              {data.hiddenIds.length > 0
                ? `${plural(data.hiddenIds.length, "partner")} hidden from every figure on this page`
                : "Hide partners (e.g. internal test partners) from these figures"}
            </summary>
            <form method="GET" action="/admin/partners/analytics" className="mt-3 space-y-3">
              <input type="hidden" name="range" value={r.key} />
              {r.key === "custom" && (
                <>
                  <input type="hidden" name="from" value={r.fromDay} />
                  <input type="hidden" name="to" value={r.toDay} />
                </>
              )}
              <div className="flex flex-wrap gap-x-5 gap-y-2">
                {data.allPartners.map((p) => (
                  <label key={p.id} className="inline-flex items-center gap-2 text-sm text-slate-300">
                    <input type="checkbox" name="hide" value={p.id} defaultChecked={hidden.has(p.id)} />
                    {p.name} <span className="font-mono text-xs text-slate-500">{p.code}</span>
                  </label>
                ))}
              </div>
              <div className="flex items-center gap-3">
                <button className="btn-ghost">Apply</button>
                {data.hiddenIds.length > 0 && (
                  <Link
                    href={`/admin/partners/analytics?${new URLSearchParams(
                      r.key === "custom" ? { range: r.key, from: r.fromDay, to: r.toDay } : { range: r.key }
                    )}`}
                    className="text-xs text-slate-500 hover:text-slate-300"
                  >
                    Show all partners
                  </Link>
                )}
              </div>
            </form>
          </details>
        )}
      </div>

      {/* Headline figures for the range */}
      <div className="grid grid-cols-2 gap-4 lg:grid-cols-3 xl:grid-cols-6">
        <StatCard
          label="Link clicks"
          value={t.clicks.toLocaleString("en-US")}
          delta={plural(t.uniqueVisitors, "unique visitor")}
        />
        <StatCard
          label="Customers attached"
          value={t.newCustomers.toLocaleString("en-US")}
          delta={`${t.newAccounts} new · ${t.existingAccounts} existing`}
        />
        <StatCard
          label="Paying customers"
          value={t.firstPurchases.toLocaleString("en-US")}
          delta="first paid purchase in range"
        />
        <StatCard
          label="Referred revenue"
          value={money(t.revenueCents)}
          delta={`net of tax · ${plural(t.charges, "charge")}`}
        />
        <StatCard
          label="Commission earned"
          value={money(t.commissionCents)}
          delta={t.revenueCents > 0 ? `${pct(t.commissionCents, t.revenueCents)} of referred revenue` : "no referred revenue"}
        />
        <StatCard label="Paid out" value={money(t.payoutsCents)} delta="payouts recorded in range" />
      </div>

      {/* All-time position */}
      <div className="card">
        <div className="flex flex-wrap items-baseline justify-between gap-2">
          <h2 className="font-semibold">Program ledger · all time</h2>
          <p className="text-xs text-slate-500">Not affected by the date range.</p>
        </div>
        <div className="mt-3 grid gap-4 sm:grid-cols-3">
          <div>
            <p className="section-label mb-1">Commission earned</p>
            <p className="text-2xl font-bold">{money(data.ledger.earnedCents)}</p>
          </div>
          <div>
            <p className="section-label mb-1">Paid out</p>
            <p className="text-2xl font-bold text-emerald-400">{money(data.ledger.paidOutCents)}</p>
          </div>
          <div>
            <p className="section-label mb-1">Owed to partners now</p>
            <p className="text-2xl font-bold text-brand-300">{money(data.ledger.owedCents)}</p>
          </div>
        </div>
        <p className="mt-3 text-xs text-slate-500">
          {plural(data.partners.total, "partner")} · {data.partners.active} active · {data.partners.withClicksEver} with at
          least one link click · {data.partners.withCustomers} with an attached customer · {data.partners.earning} earning
          commission. &ldquo;Owed&rdquo; is each partner&apos;s earned commission minus the payouts recorded for them, the same
          balance their Manage page shows.
          {data.ledger.accruedRowCents !== data.ledger.owedCents &&
            ` The Partners tab's "Accrued (unpaid)" card sums commission rows still marked accrued (${money(
              data.ledger.accruedRowCents
            )}) — it differs from this when a partial payout has been recorded.`}
        </p>
      </div>

      {/* Trends */}
      <div className="grid gap-4 xl:grid-cols-2">
        <div className="card">
          <h2 className="mb-1 font-semibold">Link clicks</h2>
          <p className="mb-3 text-xs text-slate-500">
            Visits to any partner&apos;s /partner/&lt;code&gt; (or /r/&lt;code&gt;) link, per {bucketWord}.
          </p>
          {!hasClicks ? (
            <NoData>No partner link clicks in this range.</NoData>
          ) : !chartable ? (
            <NoData>{plural(t.clicks, "click")} — pick a longer range to see a trend.</NoData>
          ) : (
            <AreaChart
              id="pp-clicks"
              series={[{ name: "Clicks", data: s.map((p) => p.clicks), color: C.clicks }]}
              height={200}
              maxY={countMax(s.map((p) => p.clicks))}
              yLabel={(v) => v.toFixed(0)}
              xLabels={xLabels}
            />
          )}
        </div>

        <div className="card">
          <h2 className="mb-1 font-semibold">New customers &amp; first purchases</h2>
          <p className="mb-3 text-xs text-slate-500">
            Customers attached to a partner, and customers making their first paid purchase, per {bucketWord}.
          </p>
          {!hasCustomers ? (
            <NoData>No customers were attached or made a first purchase in this range.</NoData>
          ) : !chartable ? (
            <NoData>Pick a longer range to see a trend.</NoData>
          ) : (
            <>
              <Legend
                items={[
                  { label: "Customers attached", color: C.customers },
                  { label: "First purchases", color: C.paying },
                ]}
              />
              <AreaChart
                id="pp-customers"
                series={[
                  { name: "Attached", data: s.map((p) => p.newCustomers), color: C.customers },
                  { name: "First purchases", data: s.map((p) => p.firstPurchases), color: C.paying },
                ]}
                height={200}
                maxY={countMax(s.flatMap((p) => [p.newCustomers, p.firstPurchases]))}
                yLabel={(v) => v.toFixed(0)}
                xLabels={xLabels}
              />
            </>
          )}
        </div>

        <div className="card">
          <h2 className="mb-1 font-semibold">Referred revenue vs. commission</h2>
          <p className="mb-3 text-xs text-slate-500">
            Net (pre-tax) charges on partner-attached customers, and the commission they earned, per {bucketWord}.
          </p>
          {!hasMoney ? (
            <NoData>No referred revenue or commission in this range.</NoData>
          ) : !chartable ? (
            <NoData>Pick a longer range to see a trend.</NoData>
          ) : (
            <>
              <Legend
                items={[
                  { label: "Referred revenue", color: C.revenue },
                  { label: "Commission", color: C.commission },
                ]}
              />
              <AreaChart
                id="pp-revenue"
                series={[
                  { name: "Revenue", data: s.map((p) => p.revenueCents), color: C.revenue },
                  { name: "Commission", data: s.map((p) => p.commissionCents), color: C.commission },
