              />
            </>
          )}
        </div>

        <div className="card">
          <h2 className="mb-1 font-semibold">Commission earned vs. paid out</h2>
          <p className="mb-3 text-xs text-slate-500">
            Running totals since the program began. The gap between the lines is what is owed.
          </p>
          {!hasLedger ? (
            <NoData>No commission has been earned yet.</NoData>
          ) : !chartable ? (
            <NoData>Pick a longer range to see a trend.</NoData>
          ) : (
            <>
              <Legend
                items={[
                  { label: "Earned (running total)", color: C.earned },
                  { label: "Paid out (running total)", color: C.paid },
                ]}
              />
              <AreaChart
                id="pp-ledger"
                series={[
                  { name: "Earned", data: s.map((p) => p.cumEarnedCents), color: C.earned },
                  { name: "Paid out", data: s.map((p) => p.cumPaidCents), color: C.paid },
                ]}
                height={200}
                maxY={moneyMax(s.flatMap((p) => [p.cumEarnedCents, p.cumPaidCents]))}
                yLabel={(v) => money(Math.round(v))}
                xLabels={xLabels}
              />
            </>
          )}
        </div>
      </div>

      <details className="card">
        <summary className="cursor-pointer select-none text-sm font-semibold text-slate-300">
          Every {bucketWord} as a table
        </summary>
        <div className="mt-3 max-h-[420px] overflow-auto">
          <table className="table-shell min-w-[760px]">
            <thead>
              <tr>
                <th>{bucketWord === "day" ? "Day" : bucketWord === "week" ? "Week of" : "Month"}</th>
                <th className="text-right">Clicks</th>
                <th className="text-right">Attached</th>
                <th className="text-right">First purchases</th>
                <th className="text-right">Referred revenue</th>
                <th className="text-right">Commission</th>
                <th className="text-right">Paid out</th>
