        ) : (
          <table className="table-shell mt-2 min-w-[980px]">
            <thead>
              <tr>
                <th>#</th>
                <th>Partner</th>
                <th className="text-right">Clicks</th>
                <th className="text-right">Attached</th>
                <th className="text-right">First purchases</th>
                <th>Referred revenue</th>
                <th className="text-right">Commission</th>
                <th className="text-right">Owed</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
