                  <td className="text-right">
                    <Link href={`/admin/partners/${p.id}`} className="text-brand-300 hover:underline">
                      Manage
                    </Link>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <div className="grid gap-4 xl:grid-cols-3">
        <div className="card">
          <h2 className="mb-1 font-semibold">What referred customers buy</h2>
          <p className="mb-4 text-xs text-slate-500">Referred revenue in this range by product.</p>
          {data.products.length === 0 ? (
            <NoData>No referred revenue in this range.</NoData>
          ) : (
            <div className="space-y-3">
              {data.products.map((p) => (
                <div key={p.label}>
                  <div className="mb-1 flex items-baseline justify-between gap-3 text-sm">
                    <span className="truncate">{p.label}</span>
                    <span className="shrink-0 tabular-nums">
                      <span className="font-mono">{money(p.revenueCents)}</span>
                      <span className="ml-2 text-xs text-slate-500">{plural(p.charges, "charge")}</span>
                    </span>
                  </div>
                  <MeterBar value={p.revenueCents} max={data.products[0].revenueCents} color="#34d399" />
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="card">
          <h2 className="mb-1 font-semibold">Where clicks come from</h2>
          <p className="mb-4 text-xs text-slate-500">The referring site the visitor&apos;s browser reported.</p>
          {t.clicks === 0 ? (
            <NoData>No partner link clicks in this range.</NoData>
          ) : (
            <div className="space-y-3">
              {data.sources.map((x) => (
                <div key={x.source}>
                  <div className="mb-1 flex items-baseline justify-between gap-3 text-sm">
                    <span className="truncate">{x.source}</span>
                    <span className="shrink-0 font-mono">{x.clicks}</span>
                  </div>
                  <MeterBar value={x.clicks} max={data.sources[0].clicks} color={C.clicks} />
                </div>
              ))}
              <p className="pt-1 text-xs text-slate-500">
                Discord, most social apps, email clients and typed links don&apos;t send a referring site, so they land in
                &ldquo;Direct / not shared&rdquo;.
              </p>
            </div>
          )}
        </div>

        <div className="card">
          <h2 className="mb-1 font-semibold">Creator recruitment</h2>
          <p className="mb-4 text-xs text-slate-500">Every creator invite, all time.</p>
          {data.invites.total === 0 ? (
            <NoData>No creator invites yet.</NoData>
          ) : (
            <dl className="grid grid-cols-2 gap-x-4 gap-y-3 text-sm">
              <div>
                <dt className="text-xs text-slate-500">Invites</dt>
                <dd className="text-lg font-bold">{data.invites.total}</dd>
              </div>
              <div>
                <dt className="text-xs text-slate-500">Claimed (became partners)</dt>
                <dd className="text-lg font-bold text-emerald-400">
                  {data.invites.accepted}
                  <span className="ml-2 text-xs font-normal text-slate-500">
                    {pct(data.invites.accepted, data.invites.total - data.invites.drafts)} of sent
                  </span>
                </dd>
              </div>
              <div>
                <dt className="text-xs text-slate-500">Sent, awaiting a claim</dt>
                <dd className="text-lg font-bold">{data.invites.outstanding}</dd>
              </div>
              <div>
                <dt className="text-xs text-slate-500">Drafts (not emailed)</dt>
                <dd className="text-lg font-bold">{data.invites.drafts}</dd>
              </div>
              <div>
                <dt className="text-xs text-slate-500">Expired / revoked</dt>
                <dd className="text-lg font-bold">{data.invites.expired + data.invites.revoked}</dd>
              </div>
              <div>
                <dt className="text-xs text-slate-500">Claimed creators with a click</dt>
                <dd className="text-lg font-bold">
                  {data.invites.claimedWithClick}
                  <span className="ml-2 text-xs font-normal text-slate-500">of {data.invites.accepted}</span>
                </dd>
              </div>
            </dl>
          )}
        </div>
      </div>

      <p className="text-xs text-slate-500">
        Referred revenue is the net (pre-tax) amount of every paid charge — not wallet top-ups — made by a partner-attached
        customer on or after the day they were attached: the same charges commission is computed on. Refunds are not
        netted out. A customer detached from a partner drops out of revenue, but the commission they already earned
        stays in the ledger.
      </p>
    </div>
  );
}

