export type CreatorRecruitment = {
  total: number;
  drafts: number;
  /** Sent and still claimable. */
  outstanding: number;
  accepted: number;
  expired: number;
  revoked: number;
  /** Accepted invites whose partner link has at least one recorded click. */
  claimedWithClick: number;
};

/**
 * Creator recruitment funnel over EVERY creator invite (PartnerInvite kind
 * CREATOR), all time: drafted -> sent -> claimed, and how many claimed creators
 * have actually had a click on their link since. States come from
 * creatorInviteState, the same classifier the invites table uses.
 */
export async function creatorRecruitmentStats(now = new Date()): Promise<CreatorRecruitment> {
  const invites = await db.partnerInvite.findMany({
    where: { kind: "CREATOR" },
    select: { acceptedAt: true, revokedAt: true, lastSentAt: true, expiresAt: true, partner: { select: { code: true } } },
  });
  const claimedCodes = [...new Set(invites.filter((i) => i.acceptedAt && i.partner).map((i) => i.partner!.code))];
  const clicked = claimedCodes.length
    ? await db.referralClick.groupBy({ by: ["code"], where: { code: { in: claimedCodes } }, _count: { _all: true } })
    : [];
  const hasClick = new Set(clicked.filter((c) => c._count._all > 0).map((c) => c.code));

  const out: CreatorRecruitment = { total: invites.length, drafts: 0, outstanding: 0, accepted: 0, expired: 0, revoked: 0, claimedWithClick: 0 };
  for (const i of invites) {
    const st = creatorInviteState(i, now);
    if (st === "draft") out.drafts++;
    else if (st === "sent") out.outstanding++;
    else if (st === "expired") out.expired++;
    else if (st === "revoked") out.revoked++;
    else {
      out.accepted++;
      if (i.partner && hasClick.has(i.partner.code)) out.claimedWithClick++;
    }
  }
  return out;
}

