import Link from "next/link";
import { StatCard, Badge } from "@/components/ui/primitives";
import { AreaChart, MeterBar } from "@/components/ui/charts";
import { formatMoney } from "@/lib/tax";
import { computeProgramAnalytics, type ProgramSeriesPoint } from "@/lib/partner-program-analytics";

// The Partners page's Overview tab: program-wide Creator Partner analytics,
// every partner combined. All figures come from lib/partner-program-analytics.ts,
// which documents the exact table and rule behind each one; this file only lays
// them out. Range + partner filter live in the URL (?tab=overview&range=…&hide=…)
// so every view is linkable and the server recomputes on each change.

export type OverviewQuery = { range?: string; from?: string; to?: string; hide?: string | string[] };

const BASE = "/admin/partners";

const RANGES: { key: string; label: string }[] = [
  { key: "7d", label: "7d" },
  { key: "30d", label: "30d" },
  { key: "90d", label: "90d" },
  { key: "12m", label: "12m" },
  { key: "all", label: "All time" },
];

const C = {
  clicks: "#22d3ee",
  customers: "#3b82f6",
  paying: "#34d399",
  revenue: "#34d399",
  commission: "#8a70fb",
  earned: "#fbbf24",
  paid: "#34d399",
};

function pct(n: number, d: number): string {
  if (d <= 0) return "—";
  const v = (n / d) * 100;
  return `${v >= 10 || v === 0 ? Math.round(v) : v.toFixed(1)}%`;
}

function plural(n: number, one: string, many = `${one}s`): string {
  return `${n.toLocaleString("en-US")} ${n === 1 ? one : many}`;
}

/** A top-of-axis value that splits into 4 round steps (AreaChart draws 4 gridlines). */
function niceMax(max: number, integer: boolean): number {
  if (max <= 0) return integer ? 4 : 400;
  const rough = max / 4;
  const pow = Math.pow(10, Math.floor(Math.log10(rough)));
  const n = rough / pow;
  let step = (n <= 1 ? 1 : n <= 2 ? 2 : n <= 2.5 ? 2.5 : n <= 5 ? 5 : 10) * pow;
  if (integer) step = Math.max(1, Math.ceil(step));
  return step * 4;
}

/** At most 6 evenly spaced x labels — AreaChart spreads whatever it is given across the full width. */
function xLabelsFor(series: ProgramSeriesPoint[]): string[] {
  const n = series.length;
  if (n <= 6) return series.map((p) => p.label);
  return Array.from({ length: 6 }, (_, i) => series[Math.round((i * (n - 1)) / 5)].label);
}

function bucketTitle(iso: string, bucket: string): string {
  const d = new Date(iso);
  if (bucket === "month") return d.toLocaleDateString("en-US", { month: "long", year: "numeric", timeZone: "UTC" });
  const day = d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" });
  return bucket === "week" ? `Week of ${day}` : day;
}

function fmtDay(ymd: string): string {
  return new Date(`${ymd}T00:00:00Z`).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    timeZone: "UTC",
  });
}

function Legend({ items }: { items: { label: string; color: string }[] }) {
  return (
    <div className="mb-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-slate-400">
      {items.map((i) => (
        <span key={i.label} className="inline-flex items-center gap-1.5">
          <span className="h-2 w-2 rounded-full" style={{ background: i.color }} />
          {i.label}
        </span>
      ))}
    </div>
  );
}

function NoData({ children }: { children: React.ReactNode }) {
  return <p className="py-10 text-center text-sm text-slate-500">{children}</p>;
}

export async function ProgramOverview({ query, currency }: { query: OverviewQuery; currency: string }) {
  const data = await computeProgramAnalytics(query);
  const money = (c: number) => formatMoney(c, currency);
  const t = data.totals;
  const r = data.range;
  const bucketWord = r.bucket;
  const hidden = new Set(data.hiddenIds);

  const href = (params: Record<string, string>) => {
    const qs = new URLSearchParams({ tab: "overview", ...params });
    for (const id of data.hiddenIds) qs.append("hide", id);
    return `${BASE}?${qs}`;
  };
  const rangeParams: Record<string, string> =
    r.key === "custom" ? { tab: "overview", range: "custom", from: r.fromDay, to: r.toDay } : { tab: "overview", range: r.key };

  const s = data.series;
  const xLabels = xLabelsFor(s);
  const chartable = s.length >= 2;
  const countMax = (vals: number[]) => niceMax(Math.max(0, ...vals), true);
  const moneyMax = (vals: number[]) => niceMax(Math.max(0, ...vals), false);
  const hasClicks = t.clicks > 0;
  const hasCustomers = t.newCustomers + t.firstPurchases > 0;
  const hasMoney = t.revenueCents + t.commissionCents > 0;
  const hasLedger = s.some((p) => p.cumEarnedCents + p.cumPaidCents > 0);
  const revenueMax = Math.max(1, ...data.rows.map((x) => x.revenueCents));

  const funnel = [
    {
      label: "Link clicks",
      value: t.clicks,
      note: `${plural(t.uniqueVisitors, "unique visitor")}${t.clicksWithoutIp ? ` · ${t.clicksWithoutIp} without an IP` : ""}`,
    },
    { label: "Clicks matched to a signup", value: t.clicksMatched, note: `${pct(t.clicksMatched, t.clicks)} of clicks` },
    {
      label: "Customers attached",
      value: t.newCustomers,
      note: `${t.newAccounts} new ${t.newAccounts === 1 ? "account" : "accounts"} · ${t.existingAccounts} existing · ${t.attachedViaMatchedClick} via a matched click`,
    },
    { label: "…of whom have paid", value: t.cohortPaid, note: `${pct(t.cohortPaid, t.newCustomers)} of attached customers` },
  ];
  const funnelMax = Math.max(1, ...funnel.map((f) => f.value));

  return (
    <div className="space-y-6">
      {/* ---------- All time ---------- */}
      <section className="space-y-3">
        <div className="flex flex-wrap items-baseline justify-between gap-2">
          <p className="section-label">Program · all time</p>
          {data.hiddenIds.length > 0 && (
            <p className="text-xs text-amber-300">{plural(data.hiddenIds.length, "partner")} hidden — see the filter below</p>
          )}
        </div>
        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
          <div className="card">
            <p className="section-label mb-1">Partners</p>
            <p className="text-2xl font-bold">{data.partners.total}</p>
            <p className="mt-1 text-xs text-slate-500">
              {data.partners.active} active · {data.partners.withClicksEver} with a link click · {data.partners.withCustomers}{" "}
              with customers · {data.partners.earning} earning
            </p>
          </div>
          <div className="card">
            <p className="section-label mb-1">Commission earned</p>
            <p className="text-2xl font-bold">{money(data.ledger.earnedCents)}</p>
            <p className="mt-1 text-xs text-slate-500">every accrued charge, voided excluded</p>
          </div>
          <div className="card">
            <p className="section-label mb-1">Paid out</p>
            <p className="text-2xl font-bold text-emerald-400">{money(data.ledger.paidOutCents)}</p>
            <p className="mt-1 text-xs text-slate-500">payouts recorded on partners&apos; Manage pages</p>
          </div>
          <div className="card">
            <p className="section-label mb-1">Owed now (unpaid)</p>
            <p className="text-2xl font-bold text-brand-300">{money(data.ledger.owedCents)}</p>
            <p className="mt-1 text-xs text-slate-500">
              earned minus paid out, per partner
              {data.ledger.accruedRowCents !== data.ledger.owedCents &&
                ` · rows still marked accrued: ${money(data.ledger.accruedRowCents)} (differs after a partial payout)`}
            </p>
          </div>
        </div>
      </section>

      {/* ---------- Selected range ---------- */}
      <section className="space-y-4">
        <p className="section-label">Selected range</p>
        <div className="card space-y-3">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="flex flex-wrap gap-2">
              {RANGES.map((x) => (
                <Link
                  key={x.key}
                  href={href({ range: x.key })}
                  className={`rounded-lg border px-3 py-1.5 text-sm ${
                    r.key === x.key
                      ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
                      : "border-white/[0.08] text-slate-400 hover:text-slate-200"
                  }`}
                >
                  {x.label}
                </Link>
              ))}
            </div>
            <p className="text-xs text-slate-500">
              {fmtDay(r.fromDay)} – {fmtDay(r.toDay)} · UTC · per {bucketWord}
            </p>
          </div>
          <form method="GET" action={BASE} className="flex flex-wrap items-end gap-3 border-t border-white/[0.06] pt-3">
            <input type="hidden" name="tab" value="overview" />
            <input type="hidden" name="range" value="custom" />
            {data.hiddenIds.map((id) => (
              <input key={id} type="hidden" name="hide" value={id} />
            ))}
            <div>
              <label className="label">From</label>
              <input className="input py-1.5" type="date" name="from" defaultValue={r.fromDay} required />
            </div>
            <div>
              <label className="label">To</label>
              <input className="input py-1.5" type="date" name="to" defaultValue={r.toDay} required />
            </div>
            <button className={`btn-ghost ${r.key === "custom" ? "text-brand-200" : ""}`}>Apply custom range</button>
          </form>
          {r.error && (
            <p className="rounded-lg border border-amber-500/35 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
              {r.error} Showing the last 30 days instead.
            </p>
          )}
          {data.allPartners.length > 0 && (
            <details className="border-t border-white/[0.06] pt-3" open={data.hiddenIds.length > 0}>
              <summary className="cursor-pointer select-none text-sm text-slate-400 hover:text-slate-200">
                {data.hiddenIds.length > 0
                  ? `${plural(data.hiddenIds.length, "partner")} hidden from every figure on this tab`
                  : "Hide partners (e.g. internal test partners) from these figures"}
              </summary>
              <form method="GET" action={BASE} className="mt-3 space-y-3">
                {Object.entries(rangeParams).map(([k, v]) => (
                  <input key={k} type="hidden" name={k} value={v} />
                ))}
                <div className="flex flex-wrap gap-x-5 gap-y-2">
                  {data.allPartners.map((p) => (
                    <label key={p.id} className="inline-flex items-center gap-2 text-sm text-slate-300">
                      <input type="checkbox" name="hide" value={p.id} defaultChecked={hidden.has(p.id)} />
                      {p.name} <span className="font-mono text-xs text-slate-500">{p.code}</span>
                    </label>
                  ))}
                </div>
                <div className="flex items-center gap-3">
                  <button className="btn-ghost">Apply</button>
                  {data.hiddenIds.length > 0 && (
                    <Link href={`${BASE}?${new URLSearchParams(rangeParams)}`} className="text-xs text-slate-500 hover:text-slate-300">
                      Show all partners
                    </Link>
                  )}
                </div>
              </form>
            </details>
          )}
        </div>

        <div className="grid grid-cols-2 gap-4 lg:grid-cols-3 xl:grid-cols-6">
          <StatCard label="Link clicks" value={t.clicks.toLocaleString("en-US")} delta={plural(t.uniqueVisitors, "unique visitor")} />
          <StatCard
            label="Customers attached"
            value={t.newCustomers.toLocaleString("en-US")}
            delta={`${t.newAccounts} new · ${t.existingAccounts} existing`}
          />
          <StatCard label="Paying customers" value={t.firstPurchases.toLocaleString("en-US")} delta="first paid purchase in range" />
          <StatCard label="Referred revenue" value={money(t.revenueCents)} delta={`net of tax · ${plural(t.charges, "charge")}`} />
          <StatCard
            label="Commission earned"
            value={money(t.commissionCents)}
            delta={t.revenueCents > 0 ? `${pct(t.commissionCents, t.revenueCents)} of referred revenue` : "no referred revenue"}
          />
          <StatCard label="Paid out" value={money(t.payoutsCents)} delta="payouts recorded in range" />
        </div>

        <div className="grid gap-4 xl:grid-cols-2">
          <div className="card">
            <h2 className="mb-1 font-semibold">Link clicks</h2>
            <p className="mb-3 text-xs text-slate-500">
              Visits to any partner&apos;s /partner/&lt;code&gt; (or /r/&lt;code&gt;) link, per {bucketWord}.
            </p>
            {!hasClicks ? (
              <NoData>No partner link clicks in this range.</NoData>
            ) : !chartable ? (
              <NoData>{plural(t.clicks, "click")} — pick a longer range to see a trend.</NoData>
            ) : (
              <AreaChart
                id="pp-clicks"
                series={[{ name: "Clicks", data: s.map((p) => p.clicks), color: C.clicks }]}
                height={200}
                maxY={countMax(s.map((p) => p.clicks))}
                yLabel={(v) => v.toFixed(0)}
                xLabels={xLabels}
              />
            )}
          </div>

          <div className="card">
            <h2 className="mb-1 font-semibold">New customers &amp; first purchases</h2>
            <p className="mb-3 text-xs text-slate-500">
              Customers attached to a partner, and customers making their first paid purchase, per {bucketWord}.
            </p>
            {!hasCustomers ? (
              <NoData>No customers were attached or made a first purchase in this range.</NoData>
            ) : !chartable ? (
              <NoData>Pick a longer range to see a trend.</NoData>
            ) : (
              <>
                <Legend
                  items={[
                    { label: "Customers attached", color: C.customers },
                    { label: "First purchases", color: C.paying },
                  ]}
                />
                <AreaChart
                  id="pp-customers"
                  series={[
                    { name: "Attached", data: s.map((p) => p.newCustomers), color: C.customers },
                    { name: "First purchases", data: s.map((p) => p.firstPurchases), color: C.paying },
                  ]}
                  height={200}
                  maxY={countMax(s.flatMap((p) => [p.newCustomers, p.firstPurchases]))}
                  yLabel={(v) => v.toFixed(0)}
                  xLabels={xLabels}
                />
              </>
            )}
          </div>

          <div className="card">
            <h2 className="mb-1 font-semibold">Referred revenue vs. commission</h2>
            <p className="mb-3 text-xs text-slate-500">
              Net (pre-tax) charges on partner-attached customers, and the commission they earned, per {bucketWord}.
            </p>
            {!hasMoney ? (
              <NoData>No referred revenue or commission in this range.</NoData>
            ) : !chartable ? (
              <NoData>Pick a longer range to see a trend.</NoData>
            ) : (
              <>
                <Legend
                  items={[
                    { label: "Referred revenue", color: C.revenue },
                    { label: "Commission", color: C.commission },
                  ]}
                />
                <AreaChart
                  id="pp-revenue"
                  series={[
                    { name: "Revenue", data: s.map((p) => p.revenueCents), color: C.revenue },
                    { name: "Commission", data: s.map((p) => p.commissionCents), color: C.commission },
                  ]}
                  height={200}
                  maxY={moneyMax(s.flatMap((p) => [p.revenueCents, p.commissionCents]))}
                  yLabel={(v) => money(Math.round(v))}
                  xLabels={xLabels}
                />
              </>
            )}
          </div>

          <div className="card">
            <h2 className="mb-1 font-semibold">Commission earned vs. paid out</h2>
            <p className="mb-3 text-xs text-slate-500">
              Running totals since the program began. The gap between the lines is what is owed.
            </p>
            {!hasLedger ? (
              <NoData>No commission has been earned yet.</NoData>
            ) : !chartable ? (
              <NoData>Pick a longer range to see a trend.</NoData>
            ) : (
              <>
                <Legend
                  items={[
                    { label: "Earned (running total)", color: C.earned },
                    { label: "Paid out (running total)", color: C.paid },
                  ]}
                />
                <AreaChart
                  id="pp-ledger"
                  series={[
                    { name: "Earned", data: s.map((p) => p.cumEarnedCents), color: C.earned },
                    { name: "Paid out", data: s.map((p) => p.cumPaidCents), color: C.paid },
                  ]}
                  height={200}
                  maxY={moneyMax(s.flatMap((p) => [p.cumEarnedCents, p.cumPaidCents]))}
                  yLabel={(v) => money(Math.round(v))}
                  xLabels={xLabels}
                />
              </>
            )}
          </div>
        </div>

        <details className="card">
          <summary className="cursor-pointer select-none text-sm font-semibold text-slate-300">
            Every {bucketWord} as a table
          </summary>
          <div className="mt-3 max-h-[420px] overflow-auto">
            <table className="table-shell min-w-[760px]">
              <thead>
                <tr>
                  <th>{bucketWord === "day" ? "Day" : bucketWord === "week" ? "Week of" : "Month"}</th>
                  <th className="text-right">Clicks</th>
                  <th className="text-right">Attached</th>
                  <th className="text-right">First purchases</th>
                  <th className="text-right">Referred revenue</th>
                  <th className="text-right">Commission</th>
                  <th className="text-right">Paid out</th>
                </tr>
              </thead>
              <tbody>
                {s.map((p) => (
                  <tr key={p.t}>
                    <td className="whitespace-nowrap text-xs text-slate-400">{bucketTitle(p.t, bucketWord)}</td>
                    <td className="text-right font-mono">{p.clicks}</td>
                    <td className="text-right font-mono">{p.newCustomers}</td>
                    <td className="text-right font-mono">{p.firstPurchases}</td>
                    <td className="text-right font-mono">{money(p.revenueCents)}</td>
                    <td className="text-right font-mono">{money(p.commissionCents)}</td>
                    <td className="text-right font-mono">{money(p.payoutsCents)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </details>

        <div className="grid gap-4 xl:grid-cols-3">
          <div className="card">
            <h2 className="mb-1 font-semibold">Click → signup → paying</h2>
            <p className="mb-4 text-xs text-slate-500">
              Link clicks in this range, then the customers attached in it and how many of them have paid since.
            </p>
            <div className="space-y-4">
              {funnel.map((f, i) => (
                <div key={f.label}>
                  <div className="mb-1 flex flex-wrap items-baseline justify-between gap-x-3 gap-y-0.5 text-sm">
                    <span className="font-medium">
                      {i + 1}. {f.label}
                    </span>
                    <span className="font-semibold tabular-nums">{f.value.toLocaleString("en-US")}</span>
                  </div>
                  <MeterBar value={f.value} max={funnelMax} color={i === 3 ? "#34d399" : "#8a70fb"} />
                  <p className="mt-1 text-xs text-slate-500">{f.note}</p>
                </div>
              ))}
            </div>
            <div className="mt-4 space-y-1.5 border-t border-white/[0.06] pt-3 text-xs text-slate-500">
              <p>
                A click is matched to a signup only when the account is created through the link itself. A creator code
                typed at checkout, an admin attach, or a signup from before click tracking has no click to match — so
                &ldquo;customers attached&rdquo; is not a click-through rate.
              </p>
              <p>&ldquo;New account&rdquo; = created at most 24 hours before it was attached.</p>
              {t.otherCodeClicks > 0 && (
                <p>
                  {plural(t.otherCodeClicks, "other link click")} carried a code that is no partner&apos;s (a peer
                  refer-a-friend code, a typo, or a deleted partner) and {t.otherCodeClicks === 1 ? "is" : "are"} not
                  counted.
                </p>
              )}
              {t.clicksTruncated && (
                <p className="text-amber-300">
                  More clicks than one page can read — click figures cover the first 200,000 only. Narrow the range.
                </p>
              )}
            </div>
          </div>

          <div className="card">
            <h2 className="mb-1 font-semibold">What referred customers buy</h2>
            <p className="mb-4 text-xs text-slate-500">Referred revenue in this range, by product.</p>
            {data.products.length === 0 ? (
              <NoData>No referred revenue in this range.</NoData>
            ) : (
              <div className="space-y-3">
                {data.products.map((p) => (
                  <div key={p.label}>
                    <div className="mb-1 flex items-baseline justify-between gap-3 text-sm">
                      <span className="truncate">{p.label}</span>
                      <span className="shrink-0 tabular-nums">
                        <span className="font-mono">{money(p.revenueCents)}</span>
                        <span className="ml-2 text-xs text-slate-500">{plural(p.charges, "charge")}</span>
                      </span>
                    </div>
                    <MeterBar value={p.revenueCents} max={data.products[0].revenueCents} color="#34d399" />
                  </div>
                ))}
              </div>
            )}
          </div>

          <div className="card">
            <h2 className="mb-1 font-semibold">Where clicks come from</h2>
            <p className="mb-4 text-xs text-slate-500">The referring site the visitor&apos;s browser reported.</p>
            {t.clicks === 0 ? (
              <NoData>No partner link clicks in this range.</NoData>
            ) : (
              <div className="space-y-3">
                {data.sources.map((x) => (
                  <div key={x.source}>
                    <div className="mb-1 flex items-baseline justify-between gap-3 text-sm">
                      <span className="truncate">{x.source}</span>
                      <span className="shrink-0 font-mono">{x.clicks}</span>
                    </div>
                    <MeterBar value={x.clicks} max={data.sources[0].clicks} color={C.clicks} />
                  </div>
                ))}
                <p className="pt-1 text-xs text-slate-500">
                  Discord, most social apps, email clients and typed links don&apos;t send a referring site, so those
                  clicks land in &ldquo;Direct / not shared&rdquo;.
                </p>
              </div>
            )}
          </div>
        </div>

        <div className="card overflow-x-auto p-0">
          <div className="px-4 pt-4">
            <p className="section-label">Partners ranked by referred revenue</p>
            <p className="mt-1 text-xs text-slate-500">
              {fmtDay(r.fromDay)} – {fmtDay(r.toDay)}; &ldquo;Owed&rdquo; is all time.
            </p>
          </div>
          {data.rows.length === 0 ? (
            <p className="px-4 py-8 text-sm text-slate-400">No partners to show.</p>
          ) : (
            <table className="table-shell mt-2 min-w-[980px]">
              <thead>
                <tr>
                  <th>#</th>
                  <th>Partner</th>
                  <th className="text-right">Clicks</th>
                  <th className="text-right">Attached</th>
                  <th className="text-right">First purchases</th>
                  <th>Referred revenue</th>
                  <th className="text-right">Commission</th>
                  <th className="text-right">Owed</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {data.rows.map((p, i) => (
                  <tr key={p.id}>
                    <td className="font-mono text-xs text-slate-500">{i + 1}</td>
                    <td>
                      <div className="flex items-center gap-2">
                        <span className="text-slate-200">{p.name}</span>
                        {p.status !== "ACTIVE" && <Badge tone="slate">{p.status.toLowerCase()}</Badge>}
                      </div>
                      <div className="text-xs text-slate-500">
                        <span className="font-mono text-brand-200">{p.code}</span> · {p.ratePct}% ·{" "}
                        {plural(p.customersTotal, "customer")} all time
                      </div>
                    </td>
                    <td className="text-right font-mono">
                      {p.clicks}
                      {p.clicks > 0 && <div className="text-[11px] text-slate-500">{p.uniqueVisitors} unique</div>}
                    </td>
                    <td className="text-right font-mono">{p.newCustomers}</td>
                    <td className="text-right font-mono">{p.firstPurchases}</td>
                    <td className="min-w-[180px]">
                      <div className="font-mono">{money(p.revenueCents)}</div>
                      {p.revenueCents > 0 && <MeterBar value={p.revenueCents} max={revenueMax} color="#34d399" className="mt-1" />}
                    </td>
                    <td className="text-right font-mono">{money(p.commissionCents)}</td>
                    <td className="text-right font-mono text-brand-300">{money(p.owedCents)}</td>
                    <td className="text-right">
                      <Link href={`${BASE}/${p.id}`} className="text-brand-300 hover:underline">
                        Manage
                      </Link>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>

        <p className="text-xs text-slate-500">
          Referred revenue is the net (pre-tax) amount of every paid charge — not wallet top-ups — made by a
          partner-attached customer on or after the moment they were attached: the same charges commission is computed
          on. Refunds are not netted out. A customer detached from a partner drops out of revenue, but the commission
          they already earned stays in the ledger.
        </p>
      </section>
    </div>
  );
}

