1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { requireArea } from "@/lib/rbac";
4	import { PageHeader, Badge, timeAgo } from "@/components/ui/primitives";
5	import { formatMoney, currentCurrency } from "@/lib/tax";
6	import { CreatePartnerForm, RevokeInviteButton } from "@/components/admin/PartnerControls";
7	import {
8	  CreateCreatorDraftsForm,
9	  PreviewCreatorInviteButton,
10	  SendAllDraftsButton,
11	  SendCreatorInviteButton,
12	} from "@/components/admin/CreatorInviteControls";
13	import { creatorInviteState, findMasterCreatorCsv } from "@/lib/partner-invite-core";
14	
15	export const dynamic = "force-dynamic";
16	
17	export default async function AdminPartnersPage() {
18	  await requireArea("billing");
19	
20	  const [partners, currency] = await Promise.all([
21	    db.referralPartner.findMany({
22	      orderBy: { createdAt: "desc" },
23	      take: 500,
24	      include: {
25	        user: { select: { email: true } },
26	        _count: { select: { customers: true } },
27	      },
28	    }),
29	    currentCurrency(),
30	  ]);
31	
32	  // Creator invites (lib/actions-partner-invite.ts) + the delivery state of
33	  // each one's latest email, from EmailLog (SENT/FAILED, and openedAt from the
34	  // tracking pixel — "opened" only when the recipient's client loads images).
35	  const creatorInvites = await db.partnerInvite.findMany({
36	    where: { kind: "CREATOR" },
37	    orderBy: { createdAt: "desc" },
38	    take: 200,
39	    include: { partner: { select: { id: true, code: true } } },
40	  });
41	  const inviteMail = creatorInvites.length
42	    ? await db.emailLog.findMany({
43	        // `startsWith` — a bespoke/hand-worded invite (e.g. lib/partner-invite-core.ts's
44	        // sendCreatorInvite custom-mailbox path, or an ad-hoc admin script) logs under
45	        // "creator_partner_invite_custom", not the plain template. An exact match here
46	        // made every custom-worded send show as "sent · not delivered" even when it sent
