// Screenshot the staging admin Partners page tabs. Reads staging admin creds
// from /root/nxeon-staging-credentials.txt (never printed).
const { chromium } = require('playwright');
const fs = require('fs');

(async () => {
  const base = process.argv[2] || 'https://staging.nxeon.cloud';
  const outDir = process.argv[3];
  const creds = fs.readFileSync('/root/nxeon-staging-credentials.txt', 'utf8');
  const email = creds.match(/Email:\s*(\S+)/)[1];
  const password = creds.match(/Password:\s*(\S+)/)[1];

  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, ignoreHTTPSErrors: true });
  const page = await ctx.newPage();
  const problems = [];
  page.on('pageerror', (e) => problems.push(`PAGEERROR ${e.message}`));
  page.on('console', (m) => { if (m.type() === 'error') problems.push(`CONSOLE ${m.text()}`); });
  page.on('response', (r) => { if (r.status() >= 500) problems.push(`HTTP ${r.status()} ${r.url()}`); });

  await page.goto(`${base}/admin/login`, { waitUntil: 'load', timeout: 45000 });
  await page.fill('#login-email', email);
  await page.fill('#login-password', password);
  await Promise.all([
    page.waitForURL((u) => !u.pathname.startsWith('/admin/login'), { timeout: 30000 }).catch(() => {}),
    page.click('button[type="submit"]'),
  ]);
  await page.waitForTimeout(1500);
  console.log('after login:', page.url());

  const shots = [
    ['overview-all', '/admin/partners'],
    ['overview-7d', '/admin/partners?tab=overview&range=7d'],
    ['overview-badrange', '/admin/partners?tab=overview&range=custom&from=2026-09-30&to=2026-09-01'],
    ['partners', '/admin/partners?tab=partners'],
    ['invites', '/admin/partners?tab=invites'],
  ];
  for (const [name, path] of shots) {
    const resp = await page.goto(`${base}${path}`, { waitUntil: 'load', timeout: 45000 });
    await page.waitForTimeout(800);
    const h1 = await page.locator('h1').first().textContent().catch(() => null);
    const active = await page.locator('nav[aria-label="Partners sections"] a[aria-current="page"]').textContent().catch(() => null);
    console.log(`${name}: HTTP ${resp && resp.status()} url=${page.url()} h1=${JSON.stringify(h1)} activeTab=${JSON.stringify(active)}`);
    await page.screenshot({ path: `${outDir}/${name}.png`, fullPage: true });
  }

  // Sidebar: the Partners entry exists and links here.
  const sidebar = await page.locator('a[href="/admin/partners"]').count();
  console.log('sidebar links to /admin/partners:', sidebar);

  // Hide filter round-trip: tick the first partner, apply, confirm the banner.
  await page.goto(`${base}/admin/partners?tab=overview`, { waitUntil: 'load' });
  const summary = page.locator('details summary', { hasText: 'Hide partners' });
  if (await summary.count()) {
    await summary.click();
    await page.locator('input[name="hide"]').first().check();
    await Promise.all([page.waitForURL(/hide=/, { timeout: 20000 }), page.locator('details form button', { hasText: 'Apply' }).click()]);
    await page.waitForTimeout(800);
    console.log('hide url:', page.url());
    console.log('hidden banner:', await page.locator('text=hidden — see the filter below').count());
    await page.screenshot({ path: `${outDir}/overview-hidden.png`, fullPage: false });
  } else {
    console.log('no hide filter rendered (no partners?)');
  }

  // Custom range form round-trip.
  await page.goto(`${base}/admin/partners?tab=overview`, { waitUntil: 'load' });
  await page.fill('input[name="from"]', '2026-09-20');
  await page.fill('input[name="to"]', '2026-09-28');
  await Promise.all([page.waitForURL(/range=custom/, { timeout: 20000 }), page.click('button:has-text("Apply custom range")')]);
  await page.waitForTimeout(800);
  console.log('custom url:', page.url(), 'range text:', await page.locator('text=/Sep 20, 2026 – Sep 28, 2026/').count());

  // Mobile width.
  const m = await browser.newContext({ viewport: { width: 390, height: 844 }, ignoreHTTPSErrors: true, storageState: await ctx.storageState() });
  const mp = await m.newPage();
  mp.on('pageerror', (e) => problems.push(`MOBILE PAGEERROR ${e.message}`));
  await mp.goto(`${base}/admin/partners`, { waitUntil: 'load' });
  await mp.waitForTimeout(800);
  const overflow = await mp.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
  console.log('mobile horizontal overflow px:', overflow);
  await mp.screenshot({ path: `${outDir}/mobile-overview.png`, fullPage: true });

  console.log('problems:', problems.length ? problems : 'none');
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

