}

input.new_string:
/**
 * One x label slot PER DATA POINT (AreaChart spaces labels evenly across the
 * width, so only a full-length array lines each label up with its own bucket),
 * blank except every k-th bucket and the last — about six visible labels.
 */
function xLabelsFor(series: ProgramSeriesPoint[]): string[] {
  const n = series.length;
  const k = Math.max(1, Math.ceil((n - 1) / 5));
  const lastMultiple = Math.floor((n - 1) / k) * k;
  return series.map((p, i) => {
    if (i === n - 1) return p.label;
    // Drop a regular label that would crowd the final one.
    if (i === lastMultiple && n - 1 - i < k * 0.6) return "";
    return i % k === 0 ? p.label : "";
  });
}

